scripts.content:
/* 斯德哥尔摩 · 状态球  |  作者 Liwe（李伟）  |  酒馆助手(JS-Slash-Runner) 脚本
   只读正文 <state> 与预设条目，不注入正文、不保存长期记忆。 */
(function(){
  if (window.__SK_ORB__) { try{ window.__SK_ORB__.destroy(); }catch(e){} }
  var Env=(function(){
    var win=window, pwin=window, pdoc=document;
    try{ if(window.parent&&window.parent!==window&&window.parent.document){
      pwin=window.parent; pdoc=window.parent.document; } }catch(e){}
    return {win:win,pwin:pwin,pdoc:pdoc};
  })();
  var pwin=Env.pwin, pdoc=Env.pdoc;

  if(!pdoc.getElementById("sk-orb-host")){
    var host=pdoc.createElement("div");
    host.id="sk-orb-host";
    host.style.cssText="all:initial;position:fixed;left:0;top:0;width:0;height:0;z-index:2147483000";
    pdoc.body.appendChild(host);
    var root=host.attachShadow({mode:"open"});
    var wrap=pdoc.createElement("div");
    wrap.innerHTML="<style>
:host{
  --bg:#e8e0d0; --paper:#fffdf7; --paper2:#f7f2e9; --line:#e3d9c4;
  /* soft：顶栏 / 头图 / 底栏专用。比 paper2 淡得多，只比面板主色深一丁点，
     目的是让面板的「头」和「尾」化进主体里，不再像两块贴上去的深色板。 */
  --soft:#fbf8f1; --lineSoft:#efe9dc;
  --ink:#2b2620; --ink2:#6b6154; --ink3:#9c9184;
  --gold:#ba7517; --gold2:#f0e0bd;
  --ring:rgba(186,117,23,.34); --ring2:rgba(186,117,23,.62);
  --red:#a83232; --red2:#f7e2e2;
  --green:#3d7a55; --green2:#f4fbf6; --greenline:#bcd9c4;
  --blue:#3a6b8c; --blue2:#e0ecf4;
  --glass:rgba(255,253,247,.90);
  --shadow:0 16px 40px rgba(60,48,30,.15),0 2px 6px rgba(60,48,30,.07);
  --r:14px;
}
:host(.night){
  --bg:#12141a; --paper:#1b1e26; --paper2:#232733; --line:#2f3542;
  --soft:#1e222b; --lineSoft:#252a34;
  --ink:#e8e4da; --ink2:#a8a29a; --ink3:#7b756c;
  --gold:#d9a54a; --gold2:#33291a;
  --ring:rgba(217,165,74,.36); --ring2:rgba(217,165,74,.70);
  --red:#e0685f; --red2:#33211f;
  --green:#6fb894; --green2:#1c2c23; --greenline:#2f5240;
  --blue:#6fa8cf; --blue2:#1e2b36;
  --glass:rgba(27,30,38,.92);
  --shadow:0 16px 40px rgba(0,0,0,.42),0 2px 6px rgba(0,0,0,.26);
}
*{box-sizing:border-box;margin:0;padding:0}
:host{
  font-family:"PingFang SC","Microsoft YaHei","Segoe UI",system-ui,sans-serif;
  background:linear-gradient(160deg,var(--bg),color-mix(in srgb,var(--bg) 80%,#000 6%));
  min-height:100vh;color:var(--ink);padding:24px;
  transition:background .35s,color .35s;
}
.ghost{max-width:620px;margin:0 auto 20px;color:var(--ink3);font-size:13px;line-height:2}
.ghost h1{font-size:19px;color:var(--ink);margin-bottom:6px;font-weight:600}
.ghost .k{color:var(--red);font-weight:600}
.ghost code{background:var(--paper2);padding:1px 6px;border-radius:5px;font-size:12px;color:var(--ink2)}

/* ===== 球 ===== */
#orb{position:fixed;right:24px;bottom:24px;width:44px;height:44px;border-radius:50%;
  border:1px solid var(--ring);box-shadow:0 4px 16px rgba(0,0,0,.16);cursor:pointer;
  overflow:hidden;z-index:900;transition:transform .22s cubic-bezier(.34,1.56,.64,1),border-color .22s;
  background:var(--paper2)}
#orb:hover{transform:scale(1.10);border-color:var(--ring2)}
#orb img{position:absolute;left:50%;top:50%;width:100%;height:100%;object-fit:contain;
  transform-origin:50% 50%;transform:translate(-50%,-50%);pointer-events:none;user-select:none}
/* 贴边吸附：球有 1/3 藏到屏幕外，整体变淡；手指/鼠标靠近再浮出来一点 */
#orb.edge{opacity:.42;box-shadow:0 2px 8px rgba(0,0,0,.10)}
#orb.edge:hover{opacity:1;box-shadow:0 4px 16px rgba(0,0,0,.16)}
#orb.edge[data-e="l"]:hover{transform:translateX(8px) scale(1.06)}
#orb.edge[data-e="r"]:hover{transform:translateX(-8px) scale(1.06)}
#orb.snapping{transition:left .26s cubic-bezier(.22,.9,.3,1),top .26s cubic-bezier(.22,.9,.3,1),
  opacity .22s,transform .22s}

/* ===== 面板 ===== */
#panel{position:fixed;right:26px;bottom:96px;width:min(430px,calc(100vw - 12px));max-height:min(80vh,780px);
  background:var(--glass);backdrop-filter:blur(18px) saturate(1.15);
  -webkit-backdrop-filter:blur(18px) saturate(1.15);
  border:1px solid var(--lineSoft);border-radius:var(--r);box-shadow:var(--shadow);
  z-index:901;display:none;flex-direction:column;overflow:hidden;
  transform-origin:bottom right;animation:pop .26s cubic-bezier(.34,1.4,.64,1);position:fixed}
#panel.open{display:flex}
@keyframes pop{from{opacity:0;transform:scale(.92) translateY(14px)}to{opacity:1;transform:none}}

/* 顶栏：底色用 soft（贴近面板主色），下边线用更淡的 lineSoft —— 不再是一条深色横杠 */
.bar{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--lineSoft);
  background:var(--soft);flex:none;
  touch-action:none;user-select:none;-webkit-user-select:none;cursor:grab}
.bar:active{cursor:grabbing}
.bar .face{position:relative;display:block;width:27px;height:27px;border-radius:50%;
  border:1.5px solid var(--gold);overflow:hidden;flex:none;background:var(--paper2)}
.bar .face img{position:absolute;left:50%;top:50%;width:100%;height:100%;object-fit:contain;
  transform-origin:50% 50%;transform:translate(-50%,-50%);pointer-events:none}
.bar .tt{flex:1;min-width:0}
.bar .tt b{font-size:13px;font-weight:600;letter-spacing:.4px;display:block}
.bar .tt span{font-size:10px;color:var(--ink3)}
.bar button{width:28px;height:28px;border-radius:8px;border:1px solid var(--line);background:var(--paper);
  color:var(--ink2);cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center;
  flex:none;transition:.16s}
.bar button:hover{background:var(--gold);color:#fff;border-color:var(--gold)}
.bar button.hot{border-color:var(--red);color:var(--red)}
.bar button.hot:hover{background:var(--red);color:#fff}
.bar button.spin{animation:rot .8s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}

.scroll{flex:1;overflow-y:auto;overscroll-behavior:contain}
.scroll::-webkit-scrollbar{width:7px}
.scroll::-webkit-scrollbar-thumb{background:var(--line);border-radius:4px}

/* 头图：底色也用 soft，跟下方 fade 的落点（paper）几乎同色 → 图片区自然化进主体 */
.hero{position:relative;height:120px;flex:none;overflow:hidden;background:var(--soft)}
.hero img{position:absolute;left:50%;top:50%;width:100%;height:100%;object-fit:contain;
  transform-origin:50% 50%;transform:translate(-50%,-50%);pointer-events:none}
.hero .fade{position:absolute;left:0;right:0;bottom:0;height:70px;
  background:linear-gradient(to bottom,transparent,var(--paper) 88%)}
.nownum{display:flex;align-items:flex-end;gap:11px;padding:2px 14px 10px;border-bottom:1px solid var(--lineSoft);
  background:var(--paper);flex:none}
.nownum .big{font-size:26px;font-weight:700;color:var(--gold);line-height:1;font-family:Georgia,serif}
.nownum .meta{flex:1;min-width:0;font-size:11px;color:var(--ink2);line-height:1.65}
.nownum .meta div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nownum .meta i{font-style:normal;color:var(--ink3)}

.sec{padding:12px 14px 4px}
.sec .hd{display:flex;align-items:center;gap:7px;font-size:10.5px;font-weight:700;letter-spacing:1.6px;
  color:var(--ink3);margin-bottom:9px}
.sec .hd::after{content:"";flex:1;height:1px;background:var(--line);order:5}
.sec.now .hd{color:var(--gold)}
.sec .hd button{order:6;width:22px;height:22px;border-radius:6px;border:1px solid var(--line);
  background:var(--paper);color:var(--ink3);cursor:pointer;font-size:11px;line-height:1;
  display:flex;align-items:center;justify-content:center;transition:.15s;padding:0}
.sec .hd button:hover{border-color:var(--gold);color:var(--gold)}
.sec .hd button.on{background:var(--gold);border-color:var(--gold);color:#fff}
.row .bg.def{background:var(--red2);border-color:var(--red);color:var(--red)}

.card{border:1px solid var(--line);border-radius:11px;padding:10px 12px;background:var(--paper);margin-bottom:9px}
.card.irr{border-color:color-mix(in srgb,var(--red) 52%,var(--line));background:var(--red2)}
.card.rel{border-color:color-mix(in srgb,var(--gold) 48%,var(--line));background:var(--gold2)}
.card .lb{font-size:10px;font-weight:700;letter-spacing:1.3px;margin-bottom:6px;display:flex;align-items:center;gap:6px}
.card.irr .lb{color:var(--red)} .card.rel .lb{color:var(--gold)}
.card .lb .n{background:var(--gold);color:#fff;border-radius:9px;padding:1px 7px;font-size:9.5px;letter-spacing:0}
.card.irr .lb .n{background:var(--red)}
.card .tx{font-size:12.5px;line-height:1.75}
.rel-item{padding:7px 0;border-top:1px dashed color-mix(in srgb,var(--gold) 32%,transparent)}
.rel-item:first-of-type{border-top:none;padding-top:0}
.rel-item .who{font-size:12px;font-weight:600;margin-bottom:3px}
.rel-item .why{font-size:11.5px;color:var(--ink2);line-height:1.65}
.rel-item .why i{font-style:normal;color:var(--ink3)}
.place{margin-bottom:8px}.place:last-child{margin-bottom:0}
.place .pn{font-size:11px;color:var(--gold);font-weight:600;margin-bottom:5px}
.chips{display:flex;flex-wrap:wrap;gap:5px}
.chip{font-size:11px;padding:3px 9px;border-radius:20px;background:var(--paper2);border:1px solid var(--line);
  white-space:nowrap}
.chip em{font-style:normal;color:var(--ink3);font-size:10px}
.chip.aff{border-color:transparent;font-variant-numeric:tabular-nums}
.chip.pos{background:color-mix(in srgb,var(--red) 14%,var(--paper2));color:var(--red)}
.chip.neg{background:var(--blue2);color:var(--blue)}
.sum{font-size:12px;line-height:1.8;color:var(--ink2)}
.sum .k{color:var(--gold);font-weight:600}

/* ===== 条目列表 ===== */
.tools{display:flex;gap:6px;margin-bottom:9px;align-items:center}
.tools .sch{flex:1;position:relative}
.tools .sch input{width:100%;padding:7px 10px 7px 27px;border-radius:9px;border:1px solid var(--line);
  background:var(--paper);color:var(--ink);font-size:12px;outline:none;font-family:inherit}
.tools .sch input:focus{border-color:var(--gold)}
.tools .sch::before{content:"⌕";position:absolute;left:9px;top:50%;transform:translateY(-50%);
  color:var(--ink3);font-size:14px}
.filt{display:flex;gap:4px;margin-bottom:9px}
.filt span{font-size:11px;padding:4px 11px;border-radius:16px;border:1px solid var(--line);
  background:var(--paper);color:var(--ink2);cursor:pointer;transition:.15s}
.filt span.on{background:var(--gold);border-color:var(--gold);color:#fff;font-weight:600}
.filt span:hover:not(.on){border-color:var(--gold)}

.list{border:1px solid var(--line);border-radius:11px;overflow:hidden;background:var(--paper)}

/* ===== 分组（v1.3）=====
   分组只是「显示层」：ITEMS 数组顺序不动，写回预设的顺序因此完全不变。 */
/* v1.6：组头与条目「同一条竖线」—— padding、gap、第一个图标占位宽度全部跟 .row 对齐，
   组名起点和下面的条目名起点严格重合，不会再看错行 */
.gh{display:flex;align-items:center;gap:9px;padding:9px 11px;background:var(--paper2);
  border-top:1px solid var(--line);cursor:pointer;user-select:none;position:relative;
  transition:background .16s}
.gh:first-child{border-top:none}
/* 展开的那组左侧亮一条金线，折叠时没有 —— 一眼看出哪几组是开着的 */
.gh::before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;
  background:transparent;transition:background .2s}
.gh.open::before{background:var(--gold)}
.gh:hover{background:color-mix(in srgb,var(--gold) 9%,var(--paper2))}
/* 箭头占位 16px = 条目拖拽手柄 .row .hdle 的 16px，居中 → 组名和条目名左边缘对齐 */
.gh .cv{flex:none;width:16px;display:flex;align-items:center;justify-content:center;
  font-size:9px;color:var(--ink3);line-height:1;
  transition:transform .22s cubic-bezier(.34,1.4,.64,1),color .2s}
.gh.open .cv{transform:rotate(90deg);color:var(--gold)}
/* v1.6：组名是标题 → 比条目名（12.5px）稍微大一点、加粗，行高跟条目一致 1.4 */
.gh .nm{flex:1;min-width:0;font-size:13.5px;font-weight:600;letter-spacing:.02em;color:var(--ink);
  line-height:1.4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* 组里开了几条：一小条比例条 + 数字，比原来的红胶囊安静 */
.gh .gb{flex:none;width:42px;height:3px;border-radius:2px;background:var(--line);overflow:hidden}
.gh .gb i{display:block;height:100%;border-radius:2px;background:var(--red);transition:width .28s}
.gh .ct{flex:none;font-size:10.5px;color:var(--ink3);font-weight:400;min-width:34px;text-align:right;
  font-variant-numeric:tabular-nums;letter-spacing:.02em}
.gh .op{display:flex;gap:2px;flex:none}
.gh .op button{width:22px;height:22px;border-radius:6px;border:1px solid transparent;background:transparent;
  color:var(--ink3);cursor:pointer;font-size:11px;display:flex;align-items:center;justify-content:center}
.gh .op button:hover{background:var(--paper);border-color:var(--line);color:var(--ink)}
.gh + .row{border-top:1px solid var(--line)}
.gh:not(.open) + .row{border-top:none}
/* 组里第一条稍微下沉一点，看起来像「属于这个组」 */
.gh.open + .row{box-shadow:inset 2px 0 0 color-mix(in srgb,var(--gold) 28%,transparent)}
.row.gHidden{display:none}
.grpEmpty{display:none}

/* ===== 手机版已删（v1.6）=====
   原本有一整套 :host(.mobile) 紧凑样式 —— 手机上把字号、头图、行距全压小，
   结果手机上比电脑版难看得多。现在所有设备一律用同一套（电脑版）样式：
   面板宽度本来就写的 min(430px, 100vw-12px)，窄屏也能自己收住，不需要另做一套。 */
.row{display:flex;align-items:center;gap:9px;padding:9px 11px;border-top:1px solid var(--line);
  transition:background .13s;position:relative}
.row:first-child{border-top:none}
.row:hover{background:var(--paper2)}
.row.slot{opacity:.62}
/* 默认开启的条目：整条偏红 + 左侧红边 */
.row.def{background:color-mix(in srgb,var(--red) 9%,var(--paper));
  box-shadow:inset 3px 0 0 var(--red)}
.row.def:hover{background:color-mix(in srgb,var(--red) 15%,var(--paper))}
.row.def .nm{color:var(--red);font-weight:600}
/* 拖拽手柄 */
.row .hdle{width:16px;flex:none;display:flex;align-items:center;justify-content:center;
  color:var(--ink3);cursor:grab;font-size:13px;
  line-height:1;user-select:none;letter-spacing:-2px;opacity:.5;transition:.15s}
.row:hover .hdle{opacity:1;color:var(--gold)}
.row .hdle:active{cursor:grabbing}
.row.dragging{opacity:.55;background:var(--gold2);box-shadow:0 4px 14px rgba(0,0,0,.2)}
.locked .row .hdle{opacity:.18;cursor:not-allowed}
.locked .row .sw{cursor:not-allowed}
.row .sw{width:34px;height:19px;border-radius:11px;background:var(--line);position:relative;
  cursor:pointer;flex:none;transition:.18s}
.row .sw::after{content:"";position:absolute;top:2px;left:2px;width:15px;height:15px;border-radius:50%;
  background:#fff;transition:.18s;box-shadow:0 1px 3px rgba(0,0,0,.25)}
.row .sw.on{background:var(--red)}
.row .sw.on::after{left:17px}
.row .sw.dis{cursor:not-allowed;opacity:.4}
.row .nm{flex:1;min-width:0;font-size:12.5px;line-height:1.4;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.row .nm .d{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:6px;vertical-align:1px}
.row .nm .d.def{background:var(--red)}
.row .nm .d.no{background:transparent;border:1px solid var(--ink3)}
.row.off .nm{color:var(--ink3)}
.row .bg{font-size:9.5px;padding:1px 6px;border-radius:7px;background:var(--paper2);
  border:1px solid var(--line);color:var(--ink3);flex:none}
.row .bg.mod{background:var(--gold2);border-color:var(--gold);color:var(--gold)}
.row .op{display:flex;gap:3px;flex:none}
.row .op button{width:25px;height:25px;border-radius:7px;border:1px solid transparent;background:transparent;
  color:var(--ink3);cursor:pointer;font-size:12px;display:flex;align-items:center;justify-content:center;transition:.14s}
.row .op button:hover{background:var(--paper2);border-color:var(--line);color:var(--ink)}
.row .op button.del:hover{background:var(--red2);color:var(--red);border-color:var(--red)}

.addbar{margin-top:9px;margin-bottom:12px;display:flex;gap:6px}
.addbar button{flex:1;padding:9px;border-radius:10px;border:1px dashed var(--gold);background:transparent;
  color:var(--gold);font-size:12px;cursor:pointer;font-family:inherit;transition:.15s}
.addbar button:hover{background:var(--gold);color:#fff;border-style:solid}
.addbar button.sec{flex:none;padding:9px 13px;border-color:var(--line);color:var(--ink2)}
.addbar button.sec:hover{background:var(--ink2);color:#fff;border-color:var(--ink2)}

.empty{padding:26px 14px;text-align:center;color:var(--ink3);font-size:12px;
  display:flex;flex-direction:column;align-items:center}
.empty b{display:block;font-size:28px;margin-bottom:8px;opacity:.4}

/* ===== 编辑器覆盖层 ===== */
#editor{position:absolute;inset:0;background:var(--paper);z-index:5;display:none;flex-direction:column}
#editor.on{display:flex}
.ed-bar{display:flex;align-items:center;gap:8px;padding:11px 13px;border-bottom:1px solid var(--line);
  background:var(--paper2);flex:none}
.ed-bar b{flex:1;font-size:13px;font-weight:600}
.ed-bar button{padding:7px 15px;border-radius:9px;border:1px solid var(--line);background:var(--paper);
  color:var(--ink2);font-size:12px;cursor:pointer;font-family:inherit}
.ed-bar button.sv{background:var(--gold);border-color:var(--gold);color:#fff;font-weight:600}
.ed-bar button.sv:hover{filter:brightness(1.08)}
.ed-body{flex:1;overflow-y:auto;padding:13px}
.ed-body label{display:block;font-size:10.5px;color:var(--ink3);letter-spacing:1px;margin:0 0 6px}
.ed-body .fld{margin-bottom:13px}
.ed-body input[type=text]{width:100%;padding:9px 11px;border-radius:9px;border:1px solid var(--line);
  background:var(--paper2);color:var(--ink);font-size:13px;outline:none;font-family:inherit}
.ed-body input[type=text]:focus{border-color:var(--gold)}
.ed-body textarea{width:100%;min-height:230px;padding:11px;border-radius:9px;border:1px solid var(--line);
  background:var(--paper2);color:var(--ink);font-size:12px;line-height:1.75;outline:none;resize:vertical;
  font-family:"Consolas","Microsoft YaHei",monospace}
.ed-body textarea:focus{border-color:var(--gold)}
.ed-body .hint{font-size:11px;color:var(--ink3);line-height:1.7;margin-top:6px}
.ed-body .sel{display:flex;gap:7px;align-items:center;padding:9px 11px;border-radius:9px;
  background:var(--paper2);border:1px solid var(--line)}
.ed-body .sel label{margin:0}
.ed-body .sel select{padding:5px 9px;border-radius:7px;border:1px solid var(--line);background:var(--paper);
  color:var(--ink);font-size:12px;font-family:inherit}
#edDel{width:100%;padding:9px;border-radius:9px;border:1px solid var(--line);background:transparent;
  color:var(--ink3);font-size:12px;cursor:pointer;font-family:inherit;transition:.15s}
#edDel:hover{background:var(--red2);border-color:var(--red);color:var(--red)}

/* ===== 更新弹窗 ===== */
.mask{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:999;display:none;align-items:center;
  justify-content:center;backdrop-filter:blur(3px)}
.mask.on{display:flex}
.dlg{width:min(360px,calc(100vw - 24px));background:var(--paper);border:1px solid var(--line);
  border-radius:13px;padding:19px;
  box-shadow:var(--shadow);max-height:80vh;overflow-y:auto}
.dlg h3{font-size:14px;margin-bottom:10px;font-weight:600;display:flex;align-items:center;gap:7px}
.dlg p{font-size:12.5px;line-height:1.8;color:var(--ink2);margin-bottom:12px}
.dlg .repo{width:100%;padding:8px 10px;border-radius:8px;border:1px solid var(--line);background:var(--paper2);
  color:var(--ink);font-size:11.5px;outline:none;font-family:Consolas,monospace;margin-bottom:11px}
.dlg .ver{display:flex;align-items:center;gap:9px;padding:11px;border-radius:10px;background:var(--paper2);
  border:1px solid var(--line);margin-bottom:11px}
.dlg .ver .a{flex:1;font-size:12px;color:var(--ink2);text-align:center}
.dlg .ver .a b{display:block;font-size:16px;color:var(--ink);margin-bottom:2px}
.dlg .ver .ar{color:var(--ink3);font-size:15px}
.dlg .ver .a.nw b{color:var(--red)}
/* 双通道选择行 */
.dlg .chan{display:flex;align-items:center;gap:9px;padding:9px 11px;margin-bottom:7px;cursor:pointer;
  border:1px solid var(--line);border-radius:10px;background:var(--paper);user-select:none}
.dlg .chan.on{border-color:var(--gold);background:var(--gold2)}
.dlg .chan .cbx{flex:none;width:15px;height:15px;border-radius:4px;border:1.5px solid var(--line);
  background:var(--paper2);position:relative}
.dlg .chan.on .cbx{border-color:var(--gold);background:var(--gold)}
.dlg .chan.on .cbx::after{content:"";position:absolute;left:4px;top:1px;width:4px;height:8px;
  border:solid #fff;border-width:0 2px 2px 0;transform:rotate(42deg)}
.dlg .chan .cx{flex:1;min-width:0}
.dlg .chan .cx b{display:block;font-size:12.5px;color:var(--ink)}
.dlg .chan .cx span{font-size:10.5px;color:var(--ink3)}
.dlg .chan em{flex:none;font-style:normal;font-size:10.5px;color:var(--ink3)}
.dlg .chan.on em{color:var(--gold)}
.dlg .chan.na{opacity:.55;cursor:not-allowed;border-style:dashed}
.dlg .chan.na .cbx{visibility:hidden}
.dlg .log{font-size:11.5px;line-height:1.85;color:var(--ink2);background:var(--paper2);border-radius:9px;
  padding:10px 12px;margin-bottom:13px;max-height:150px;overflow-y:auto}
.dlg .log div{padding-left:13px;position:relative}
.dlg .log div::before{content:"·";position:absolute;left:3px;color:var(--gold)}
.dlg .claim{background:var(--gold2);border:1px solid var(--gold);border-radius:10px;padding:11px 13px;
  margin-bottom:13px;font-size:11.5px;line-height:1.75;color:var(--ink2)}
.dlg .claim .ch{font-size:12.5px;color:var(--ink);margin-bottom:6px;padding-bottom:6px;
  display:flex;align-items:center;gap:6px;
  border-bottom:1px dashed color-mix(in srgb,var(--gold) 45%,transparent)}
.dlg .claim div{padding-left:13px;position:relative}
.dlg .claim .ch{padding-left:0}
.dlg .claim div:not(.ch)::before{content:"§";position:absolute;left:0;color:var(--gold);font-size:10px}
.dlg .bt{display:flex;gap:8px;justify-content:flex-end}
/* 点星引导（v1.8）：跟主按钮分开的一小条，颜色只用变量，日夜都跟着走 */
.dlg .star{display:flex;align-items:center;gap:6px;margin-top:10px;padding-top:8px;
  border-top:1px solid var(--lineSoft)}
.dlg .star .stx{flex:1;min-width:0;font-size:10.5px;line-height:1.45;color:var(--ink3)}
.dlg .star button{flex:none;padding:3px 8px;font-size:10.5px;border-radius:7px;
  border:1px solid var(--line);background:var(--paper2);color:var(--ink2)}
.dlg .star button:hover{color:var(--gold);border-color:var(--gold)}
.dlg .star button:active{background:var(--gold2)}
/* 辅助区：把「顺手工具」和「主操作」在视觉上分开，别堆成一排按钮 */
.dlg .aside{margin:12px 0 10px;padding:9px 11px;border-radius:10px;background:var(--paper2);
  border:1px solid var(--line)}
.dlg .aside .as-hd{font-size:11px;color:var(--ink3)}
.dlg .aside .bt{margin-top:7px;justify-content:flex-start}
.dlg .aside .bt button{padding:7px 12px;font-size:12px}
/* 三个按钮均分（新版本提醒那屏） */
.dlg .bt.three{margin-top:12px}
.dlg .bt.three button{flex:1;padding:9px 4px;font-size:12px;min-width:0;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* 两条通道都没勾 → 「更新」按钮变灰，别让人点了没反应 */
.dlg .bt button:disabled{opacity:.42;cursor:not-allowed;filter:grayscale(.5)}
/* 设置行：一行说明 + 小开关 */
.dlg .aset{display:flex;align-items:center;gap:9px;margin-top:8px;font-size:12px;color:var(--ink2)}
.dlg .aset .tg{flex:none;width:34px;height:19px;border-radius:11px;background:var(--line);
  position:relative;cursor:pointer;transition:background .18s}
.dlg .aset .tg::after{content:"";position:absolute;top:2px;left:2px;width:15px;height:15px;border-radius:50%;
  background:#fff;transition:left .18s;box-shadow:0 1px 3px rgba(0,0,0,.25)}
.dlg .aset .tg.on{background:var(--red)}
.dlg .aset .tg.on::after{left:17px}
.dlg button{padding:8px 17px;border-radius:9px;font-size:12.5px;cursor:pointer;border:1px solid var(--line);
  background:var(--paper);color:var(--ink2);font-family:inherit}
.dlg button.go{background:var(--red);border-color:var(--red);color:#fff}
.dlg button.go:hover{filter:brightness(1.08)}
.dlg button:disabled{opacity:.5;cursor:default}
.spinrow{display:flex;align-items:center;gap:9px;justify-content:center;padding:14px;color:var(--ink2);font-size:12.5px}
.spinrow .sp{width:16px;height:16px;border:2px solid var(--line);border-top-color:var(--gold);
  border-radius:50%;animation:rot .8s linear infinite}

/* ===== 底部 =====
   两层：上面一行是状态（弱，只做信息）；下面一行是操作（强，四个等宽按钮）。
   主色只给最高频的「采集」，其余一律次级描边——避免三个金按钮把主次糊掉。 */
/* 底栏：顶上 22px 从主色渐变到 soft —— 没有硬边，看上去是面板自己收的尾 */
.foot{flex:none;padding:9px 14px calc(9px + env(safe-area-inset-bottom,0px));
  border-top:1px solid var(--lineSoft);
  background:linear-gradient(to bottom,var(--paper) 0,var(--soft) 22px)}
.foot .st{font-size:10.5px;color:var(--ink3);line-height:1.55;min-width:0}
.foot .st b{color:var(--ink2)}
.foot .frow{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:8px}
.foot .frow button{padding:7px 4px;border-radius:9px;font-size:11.5px;font-family:inherit;cursor:pointer;
  border:1px solid var(--gold);background:transparent;color:var(--gold);transition:.16s;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.foot .frow button:hover{background:var(--gold);color:#fff}
.foot .frow button.gy{border-color:var(--line);color:var(--ink2)}
.foot .frow button.gy:hover{background:var(--ink2);color:#fff}
/* 自动采集开关：和按钮同一套尺寸，只是弱化 + 带状态点，不抢戏 */
.foot .frow button.tg{border-color:var(--line);color:var(--ink3);
  display:flex;align-items:center;justify-content:center;gap:5px}
.foot .frow button.tg i{width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.4;flex:none}
.foot .frow button.tg.on{color:var(--gold);border-color:var(--ring2)}
.foot .frow button.tg.on i{opacity:1}
.foot .frow button.tg:hover{background:transparent;color:var(--gold);border-color:var(--gold)}

#toast{position:fixed;right:26px;bottom:96px;z-index:998;background:var(--ink);color:var(--paper);
  font-size:12px;padding:9px 15px;border-radius:9px;opacity:0;transition:.25s;pointer-events:none;
  box-shadow:var(--shadow)}
#toast.on{opacity:1;transform:translateY(-6px)}
/* ===== SVG 图标（替代 emoji）===== */
.ic{width:15px;height:15px;display:block;flex:none;fill:none;
  stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.ic.sm{width:13px;height:13px}
.ic.lg{width:17px;height:17px}
.ic.fill{fill:currentColor;stroke:none}
.bar button .ic,.sec .hd button .ic,.row .op button .ic{margin:0 auto}
button{display:inline-flex;align-items:center;justify-content:center}
.addbar button .ic,.foot button .ic{display:inline-block;vertical-align:-2px;margin-right:5px}
.dlg .log .ic{display:inline-block;vertical-align:-2px;margin-right:4px;stroke-width:2}
.dlg .log .ic.k{color:var(--gold);stroke:var(--gold)}
.empty .ic{width:30px;height:30px;stroke-width:1.4;color:var(--ink3);margin-bottom:6px}

/* ===== v8 · 按重要度排布 ===== */
.bk{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-bottom:8px}
.bk-hd{font-size:11px;letter-spacing:.08em;color:var(--ink3);font-weight:600;margin-bottom:6px;display:flex;align-items:center;gap:6px}
.bk-hd .n{background:var(--gold2);color:var(--gold);border-radius:6px;padding:0 6px;font-size:10px}
/* 不可逆：必须走变量。写死 #fff6f6/#fff 会在夜间模式留一块亮斑 */
.bk.irr{border-color:color-mix(in srgb,var(--red) 52%,var(--line));
  background:linear-gradient(180deg,var(--red2),var(--paper))}
.bk.irr .bk-hd{color:var(--red)}
.bk.irr .bk-tx{font-size:12.5px;line-height:1.8;color:var(--ink)}
.bk.flat{background:transparent;border-style:dashed}
.rel{padding:7px 0;border-top:1px dashed var(--line)}
.rel:first-of-type{border-top:0}
.rel-hd{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
.rel-hd .who{font-weight:700;font-size:13.5px;color:var(--ink)}
.aff{font-size:11px;font-weight:700;border-radius:6px;padding:1px 5px}
.aff.pos{color:#fff;background:var(--red)}
.aff.neg{color:#fff;background:var(--green)}
.affbar{position:relative;display:inline-block;width:56px;height:6px;background:var(--paper2);border-radius:3px;overflow:hidden;vertical-align:middle}
.affbar:before{content:"";position:absolute;left:50%;top:0;bottom:0;width:1px;background:var(--line)}
.affbar i{position:absolute;top:0;bottom:0}
.affbar i.p{left:50%;background:var(--red)}
.affbar i.n{right:50%;background:var(--green)}
.affbar i.z{display:none}
.new{font-size:10px;color:var(--gold);border:1px solid var(--gold);border-radius:6px;padding:0 5px}
.rel-tags{display:flex;flex-wrap:wrap;gap:4px;margin-top:5px}
.tag{font-size:11px;background:var(--paper2);border:1px solid var(--line);border-radius:6px;padding:1px 7px;color:var(--ink2)}
.rel-base{font-size:11px;color:var(--ink3);margin-top:4px}
.sc-line{font-size:12.5px;color:var(--ink2);margin-bottom:6px;line-height:1.7}
.sc-line em{font-style:normal;color:var(--ink3)}
.place{display:flex;gap:8px;align-items:flex-start;margin-top:5px}
.pn{font-size:11px;color:var(--ink3);flex:0 0 auto;padding-top:2px}
.chips{display:flex;flex-wrap:wrap;gap:4px}
.chip{font-size:11px;background:var(--paper2);border:1px solid var(--line);border-radius:20px;padding:2px 9px;color:var(--ink)}
.chip b{margin-left:4px;font-size:10.5px}
.chip b.pos{color:var(--red)}
.chip b.neg{color:var(--green)}
.sum{font-size:12px;line-height:1.8;color:var(--ink2);cursor:pointer}
.sum.clamp{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sum .k{color:var(--gold)}
.fold{border:1px solid var(--line);border-radius:10px;margin-bottom:8px;overflow:hidden;background:var(--paper)}
.fold-hd{display:flex;align-items:center;gap:6px;padding:8px 11px;cursor:pointer;font-size:11.5px;color:var(--ink2);user-select:none}
.fold-hd .ft{font-weight:600;letter-spacing:.06em;color:var(--ink3)}
.fold-hd .fc{margin-left:auto;font-size:10.5px;color:var(--ink3)}
.fold-hd .fa{width:0;height:0;border-left:4px solid transparent;border-right:4px solid transparent;border-top:5px solid var(--ink3);transition:transform .18s}
.fold.open .fold-hd .fa{transform:rotate(180deg)}
.fold-bd{display:none;padding:0 11px 10px}
.fold.open .fold-bd{display:block}
.thr{padding:6px 0;border-top:1px dashed var(--line);font-size:12px}
.thr:first-child{border-top:0}
.thr .eta{font-weight:700;color:var(--gold);margin-right:6px}
.thr .rm{font-size:10.5px;background:var(--gold2);color:var(--gold);border-radius:6px;padding:0 6px;margin-right:6px}
.thr .tw{color:var(--ink);font-weight:600;margin-right:6px}
.thr .tt{color:var(--ink2);margin-top:3px}
.thr .tt em{font-style:normal;color:var(--ink3);font-size:11px}
.gap{padding:6px 0;border-top:1px dashed var(--line);font-size:12px}
.gap:first-child{border-top:0}
.gap .gn{font-weight:600;color:var(--ink);margin-right:6px}
.gap .gi{color:var(--ink2);margin-right:8px}
.gap.off .gi{color:var(--ink3)}
.anch{padding:7px 0;border-top:1px dashed var(--line)}
.anch:first-child{border-top:0}
.anch .ah{display:flex;align-items:center;gap:7px}
.anch .who{font-weight:700;font-size:13px}
.anch .ag{font-size:10.5px;color:var(--ink3)}
.anch .ap{font-size:11px;color:var(--ink3);margin-top:3px}
.anch .kv{display:flex;flex-wrap:wrap;gap:5px;margin-top:5px}
.anch .kv span{font-size:11px;background:var(--paper2);border-radius:6px;padding:1px 7px;color:var(--ink2)}
.anch .kv i{font-style:normal;color:var(--gold);font-weight:700;margin-right:4px}
.anch .av{font-size:11.5px;color:var(--ink2);margin-top:5px;line-height:1.7}
#orb{cursor:grab}
#orb:active{cursor:grabbing}
#panel .bar{cursor:grab}
#panel .bar:active{cursor:grabbing}
/* ===== 头像弹窗（轻量，不抢戏）===== */
.avsec{margin:9px 0 2px}
.avhd{font-size:11.5px;color:var(--ink3);display:flex;align-items:baseline;gap:8px;margin-bottom:5px}
.avhd .at{font-size:11.5px;color:var(--ink2);font-weight:600}
.avhd span{font-size:10.5px;color:var(--ink3);opacity:.72}
.avhd .avrs{margin-left:auto;font-size:10px;color:var(--ink2);background:var(--paper);
  border:1px solid var(--line);border-radius:6px;padding:1px 8px;cursor:pointer}
.avhd .avrs:hover{color:var(--red);border-color:var(--red)}
.avrow{display:flex;gap:6px;flex-wrap:wrap}
.avc{position:relative;width:50px;padding:0;border:1.5px solid var(--line);background:var(--paper);
  border-radius:9px;cursor:pointer;overflow:hidden;display:flex;flex-direction:column;align-items:center;
  transition:border-color .15s,transform .15s}
.avc:hover{transform:translateY(-1px)}
.avc img{width:100%;height:48px;object-fit:cover;display:block;background:var(--paper2)}
.avc i{font-style:normal;font-size:9px;color:var(--ink2);padding:2px 0 3px;line-height:1;
  max-width:46px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.avc.on{border-color:var(--gold);box-shadow:0 0 0 2px var(--gold2)}
.avc .ck{position:absolute;top:2px;right:2px;width:14px;height:14px;border-radius:50%;background:var(--gold);
  color:#fff;font-size:9px;line-height:14px;text-align:center;font-weight:700}
.avhint{font-size:11px;line-height:1.7;color:var(--ink3);margin:12px 0 6px}
.avhint b{color:var(--gold);font-weight:600}
.avjson{width:100%;height:170px;font:11px/1.5 Consolas,monospace;color:var(--ink2);
  background:var(--paper2);border:1px solid var(--line);border-radius:8px;
  padding:8px;resize:none;margin-bottom:8px}
.avclip{display:flex;flex-direction:column;align-items:center;gap:8px;padding:10px;
  border:1px dashed var(--line);border-radius:10px;background:var(--paper2)}
.avzr{display:flex;align-items:center;gap:8px;width:100%;max-width:330px}
.avzoom{flex:1;min-width:0;accent-color:var(--gold);height:22px;cursor:pointer}
.avzb{width:30px;height:30px;border-radius:8px;border:1px solid var(--line);background:var(--paper);
  color:var(--ink2);font-size:15px;line-height:1;cursor:pointer;flex:none;font-family:inherit}
.avzb:hover{background:var(--gold);color:#fff;border-color:var(--gold)}
.avzr b{font-size:11px;color:var(--ink2);width:48px;text-align:right;font-weight:600;flex:none}
.avframe{position:relative;overflow:hidden;background:var(--paper);cursor:grab;touch-action:none;
  border:1px solid var(--line);flex:none}
.avframe:active{cursor:grabbing}
.avframe.sq{width:118px;height:118px;border-radius:50%}
.avframe.hz{width:min(330px,calc(100vw - 64px));height:92px;border-radius:8px}
.avframe img{position:absolute;left:50%;top:50%;width:100%;height:100%;object-fit:contain;
  transform-origin:50% 50%;pointer-events:none;user-select:none;-webkit-user-drag:none}
.avc .avnone{display:flex;align-items:center;justify-content:center;height:54px;width:100%;color:var(--ink3)}
/* ===== 更新弹窗：合并清单 ===== */
.planbox{display:flex;gap:8px;margin:10px 0 4px}
.planbox .pb{flex:1;text-align:center;background:var(--paper);border:1px solid var(--line);
  border-radius:10px;padding:9px 6px}
.planbox .pb b{display:block;font-size:20px;line-height:1.15;color:var(--ink)}
.planbox .pb span{font-size:10.5px;color:var(--ink3)}
/* 新增 / 保留 / 删除 三色一律走变量，夜间才不会留亮斑 */
.planbox .pb.ad{border-color:var(--greenline);background:var(--green2)}
.planbox .pb.ad b{color:var(--green)}
.planbox .pb.kp{border-color:var(--gold);background:var(--gold2)}
.planbox .pb.kp b{color:var(--gold)}
.planbox .pb.rm{border-color:color-mix(in srgb,var(--red) 45%,var(--line));background:var(--red2)}
.planbox .pb.rm b{color:var(--red)}
/* 「新版没有」的那几条：必须把名字摆出来让你自己看。
   这里面混着两种东西 —— 你自己加的，和作者在新版里删掉的（脚本没有历史版本可对照，
   分不出来），所以不替你判断，只列名字 + 给一个你自己点的移除入口。 */
.keeplist{margin-top:7px;padding:7px 9px;border-radius:8px;background:var(--paper2);
  border:1px solid var(--line);max-height:120px;overflow-y:auto}
.keeplist div{font-size:11.5px;line-height:1.8;color:var(--ink2);white-space:nowrap;
  overflow:hidden;text-overflow:ellipsis}
.keeplist .kmore{color:var(--ink3)}
.keeplist+.kdrop{margin-top:7px;width:100%;padding:7px 10px;font-size:12px;
  border-radius:8px;border:1px solid var(--line);background:var(--paper);color:var(--ink2)}
.keeplist+.kdrop:hover{color:var(--red);border-color:var(--red)}
.uplegend{margin:8px 0 0;padding-left:16px;font-size:11.5px;line-height:1.85;color:var(--ink2)}
.uplegend li{margin:0 0 2px}
.uplegend b{color:var(--ink)}
.upwarn{font-size:11.5px;line-height:1.8;color:var(--red);
  background:var(--red2);
  border:1px solid color-mix(in srgb,var(--red) 45%,var(--line));
  border-radius:8px;padding:8px 10px;margin:2px 0 12px}
/* ===== 更新弹窗：版本列表（最新在上，老版本折叠）=====
   配色全部走主题变量，跟条目分组那套 .gh 组头是同一套语言 */
.vlist{margin:2px 0 8px}
.vrow{border:1px solid var(--line);border-radius:10px;margin-bottom:6px;overflow:hidden;
  background:var(--paper)}
.vrow.latest{border-color:var(--gold)}
.vhd{display:flex;align-items:center;gap:7px;padding:8px 10px;cursor:pointer;user-select:none;
  background:var(--paper2)}
.vrow.latest .vhd{background:var(--gold2)}
.vhd:hover{background:var(--gold2)}
.vhd .cv{font-size:9px;color:var(--ink3);transition:transform .18s;flex:none}
.vrow.open .vhd .cv{transform:rotate(90deg)}
.vhd .nm{flex:1;min-width:0;font-size:12px;font-weight:600;color:var(--ink);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.vhd .vdate{font-size:10px;color:var(--ink3);flex:none}
.vtag{font-size:9.5px;border-radius:20px;padding:1px 6px;flex:none}
.vtag.new{background:var(--gold);color:#fff}
.vtag.cur{background:var(--blue2);color:var(--blue)}
.vbd{display:none;padding:8px 10px 10px}
.vrow.open .vbd{display:block}
.vbd .vvs{font-size:10.5px;color:var(--ink3);margin-bottom:7px}
.vbd .log{max-height:130px}
.vbd .vbt{display:flex;justify-content:flex-end;margin-top:8px}
