/* ==========================================================================
 * 斯德哥尔摩 · 状态采集器
 * 从最新 AI 楼层的原始正文里抠出 <state> / <anchor>，切成结构化数据。
 * 纯函数，无 DOM 依赖 —— 浏览器插件与 node 测试都能直接跑。
 *
 * 设计原则（回应"文字不能只是装饰"）：
 *   1. 宽容解析 —— 不预设字段清单，AI 吐什么就收什么
 *   2. 缺失即隐藏 —— 字段没有就不产出该字段，绝不编造占位值
 *   3. 分隔符全兼容 —— 冒号 : ： / 竖线 | ｜ / 分号 ; ；
 * ========================================================================== */
'use strict';

/** 统一分隔符：把各种全角/变体归一成半角 */
function norm(s) {
  return String(s == null ? '' : s)
    .replace(/：/g, ':')   // 全角冒号
    .replace(/｜/g, '|')   // 全角竖线
    .replace(/；/g, ';')   // 全角分号
    .replace(/，/g, ',');  // 全角逗号
}

/** 按分号切多条（半角/全角都已归一），并去掉空段 */
function splitMulti(s) {
  return norm(s).split(';').map(x => x.trim()).filter(Boolean);
}

/* --------------------------------------------------------------------------
 * 1. 抠块
 * ------------------------------------------------------------------------ */

/** 取出 <state>...</state> 的正文；没有就返回 null */
function extractBlock(mes, tag) {
  const re = new RegExp('<' + tag + '>([\s\S]*?)</' + tag + '>', 'i');
  const m = String(mes || '').match(re);
  return m ? m[1] : null;
}

/** 把块内按行切成 { 字段名: [值, ...] }（同名多行合并成数组） */
function blockToFields(block) {
  const out = {};
  if (!block) return out;
  let cur = null;                           // 当前键（用于收多行值）
  block.split(/?
/).forEach(line => {
    const m = line.match(/^\s*\[([^\]]+)\]\s*(.*)$/);
    if (m) {
      const key = m[1].trim();
      const val = m[2].trim();
      cur = key;
      if (val) (out[key] = out[key] || []).push(val);   // 空值不收，避免产出空卡
      return;
    }
    /* 续行：真实写法里 [关系] / [在场] 常常带值换行，后面几行属于同一个键 */
    const t = line.trim();
    if (!t || !cur) return;
    (out[cur] = out[cur] || []).push(t);
  });
  return out;
}

/* --------------------------------------------------------------------------
 * 2. 各字段的结构化
 * ------------------------------------------------------------------------ */

/** [在场] 宴会厅:格里菲斯,卡思嘉；门外:里基特(在马厩)
 *  → [{ place, people:[{name, note}] }] */
function parsePresent(arr) {
  const out = [];
  (arr || []).forEach(raw => {
    splitMulti(raw).forEach(seg => {
      const i = norm(seg).indexOf(':');
      if (i < 0) return;
      const place = norm(seg).slice(0, i).trim();
      const people = norm(seg).slice(i + 1).split(',')
        .map(x => x.trim()).filter(Boolean)
        .map(x => {
          const mm = x.match(/^([^(]+?)\s*\(([^)]*)\)$/);
          return mm ? { name: mm[1].trim(), note: mm[2].trim() }
                    : { name: x, note: '' };
        });
      if (place && people.length) out.push({ place: place, people: people });
    });
  });
  return out;
}

/** [关系] 名→user: 认知:X|意愿:Y|边界:Z|基于:W|上次变化:R127  （多条用 ; 分隔）
 *  → [{ name, know, will, edge, base, at }] */
function parseRelations(arr) {
  const out = [];
  (arr || []).forEach(raw => {
    splitMulti(raw).forEach(seg => {
      const s = norm(seg);
      const i = s.indexOf(':');
      if (i < 0) return;
      let name = s.slice(0, i).trim().replace(/→.*$/, '').trim();
      const body = s.slice(i + 1);
      const o = { name: name, know: '', will: '', edge: '', base: '', at: '', tags: [] };
      body.split('|').forEach(p => {
        const t = p.trim();
        if (!t) return;
        const c = t.indexOf(':');
        /* 没有 `键:` 前缀的裸段 = 态度词（真实写法：嫌恶避让|极度抗拒|防备变态） */
        if (c < 0) { o.tags.push(t); return; }
        const k = t.slice(0, c).trim();
        const v = t.slice(c + 1).trim();
        if (k === '认知') o.know = v;
        else if (k === '意愿') o.will = v;
        else if (k === '边界') o.edge = v;
        else if (k === '基于') o.base = v;
        else if (k === '上次变化') o.at = v;
        else o.tags.push(t);
      });
      /* 兼容：旧写法只有 认知:，新写法只有裸标签 —— 统一成有东西可显示 */
      if (!o.know && o.tags.length) o.know = o.tags.join(' · ');
      if (o.name) out.push(o);
    });
  });
  return out;
}

/** [不可逆] R4: 内容…   → [{ at, text }]（兼容无冒号写法） */
function parseIrr(arr) {
  const out = [];
  (arr || []).forEach(raw => {
    splitMulti(raw).forEach(seg => {
      const s = norm(seg);
      const i = s.indexOf(':');
      if (i < 0) { if (s) out.push({ at: '', text: s }); return; }
      out.push({ at: s.slice(0, i).trim(), text: s.slice(i + 1).trim() });
    });
  });
  return out;
}

/** [暗线] R84: 原作/外部危机|暗杀小队|内容|预计R128|触发中  （多条用 ; 分隔）
 *  → [{ at, scope, who, what, eta, state }] */
function parseThreads(arr) {
  const out = [];
  (arr || []).forEach(raw => {
    splitMulti(raw).forEach(seg => {
      const p = norm(seg).split('|');
      const head = (p[0] || '').trim();
      const mi = head.indexOf(':');
      const at = mi >= 0 ? head.slice(0, mi).trim() : head;
      const scope = mi >= 0 ? head.slice(mi + 1).trim() : '';
      out.push({
        at: at,
        scope: scope,
        who: (p[1] || '').trim(),
        what: (p[2] || '').trim(),
        eta: (p[3] || '').trim().replace(/^预计/, ''),
        state: (p[4] || '').trim()
      });
    });
  });
  return out.filter(t => t.what || t.who);
}

/** [信息差] 布鲁诺: 以为X|不知道Y; 里苏特: 认定Z|不知道W
 *  → [{ name, items:[...] }] */
function parseInfoGap(arr) {
  const out = [];
  (arr || []).forEach(raw => {
    splitMulti(raw).forEach(seg => {
      const s = norm(seg);
      const i = s.indexOf(':');
      if (i < 0) return;
      out.push({
        name: s.slice(0, i).trim(),
        items: s.slice(i + 1).split('|').map(x => x.trim()).filter(Boolean)
      });
    });
  });
  return out;
}

/** [好感] 名字: -6  → [{ name, value }] */
function parseAffection(fields) {
  const out = [];
  (fields['好感'] || []).forEach(raw => {
    const s = norm(raw);
    const i = s.lastIndexOf(':');
    if (i < 0) return;
    const v = parseInt(s.slice(i + 1), 10);
    if (isNaN(v)) return;
    out.push({ name: s.slice(0, i).trim(), value: v });
  });
  return out;
}

/** 角色锚正文兼容两种真实格式：
 *  A) 位置式： 16|欲望|恐惧|底线|自欺|对user认知        （jojo5 风格）
 *  B) 键值式： 欲望:X|恐惧:Y|底线:Z|自欺:W|对user认知:V （全职猎人风格，无年龄）
 */
function parseAnchorBody(body) {
  const o = { age: '', desire: '', fear: '', line: '', lie: '', viewOfUser: '' };
  const parts = norm(body).split('|').map(x => x.trim()).filter(Boolean);
  const hasKey = parts.some(p => /^(年龄|欲望|恐惧|底线|自欺|对user认知|认知)\s*[:]/.test(p));
  if (hasKey) {
    parts.forEach(p => {
      const c = p.indexOf(':');
      if (c < 0) return;
      const k = p.slice(0, c).trim();
      const v = p.slice(c + 1).trim();
      if (k === '年龄') o.age = v;
      else if (k === '欲望') o.desire = v;
      else if (k === '恐惧') o.fear = v;
      else if (k === '底线') o.line = v;
      else if (k === '自欺') o.lie = v;
      else if (k === '对user认知' || k === '认知') o.viewOfUser = v;
    });
  } else {
    o.age = parts[0] || '';
    o.desire = parts[1] || '';
    o.fear = parts[2] || '';
    o.line = parts[3] || '';
    o.lie = parts[4] || '';
    o.viewOfUser = parts[5] || '';
  }
  return o;
}

/** [角色锚] 名: <body> */
function parseAnchors(fields) {
  const map = {};
  (fields['角色锚'] || []).forEach(raw => {
    const s = norm(raw);
    const i = s.indexOf(':');
    if (i < 0) return;
    const name = s.slice(0, i).trim();
    map[name] = map[name] || {};
    Object.assign(map[name], parseAnchorBody(s.slice(i + 1)));
  });
  (fields['社会位置'] || []).forEach(raw => {
    const s = norm(raw);
    const i = s.indexOf(':');
    if (i < 0) return;
    const name = s.slice(0, i).trim();
    map[name] = map[name] || {};
    map[name].position = s.slice(i + 1).trim();
  });
  // 好感挂回同一个角色
  parseAffection(fields).forEach(a => {
    map[a.name] = map[a.name] || {};
    map[a.name].affection = a.value;
  });
  return Object.keys(map).map(k => Object.assign({ name: k }, map[k]));
}

/* --------------------------------------------------------------------------
 * 3. 主入口
 * ------------------------------------------------------------------------ */

/**
 * @param {string} mes  最新 AI 楼层的原始正文
 * @returns {object} 结构化状态；缺失字段一律不产出（null / 空数组）
 */
function collect(mes) {
  const stateRaw = extractBlock(mes, 'state');
  const anchorRaw = extractBlock(mes, 'anchor');

  if (!stateRaw && !anchorRaw) {
    return { ok: false, reason: 'no-state-block' };
  }

  const F = blockToFields(stateRaw);
  const A = blockToFields(anchorRaw);
  const one = k => (F[k] && F[k][0]) || null;

  const turnRaw = one('回合');
  const turn = parseInt(String(turnRaw || '').replace(/[^0-9]/g, ''), 10);
  const chapterRaw = one('章节');
  const chapter = parseInt(String(chapterRaw || '').replace(/[^0-9]/g, ''), 10);

  const relations = parseRelations(F['关系']);
  const threads = parseThreads(F['暗线']);

  // 会算的信号：本轮变动 / 暗线倒计时
  relations.forEach(r => {
    const n = parseInt(String(r.at || '').replace(/[^0-9]/g, ''), 10);
    r.atNum = isNaN(n) ? null : n;
    r.isNow = r.atNum != null && !isNaN(turn) && r.atNum === turn;
  });
  threads.forEach(t => {
    const a = parseInt(String(t.at || '').replace(/[^0-9]/g, ''), 10);
    const e = parseInt(String(t.eta || '').replace(/[^0-9]/g, ''), 10);
    t.atNum = isNaN(a) ? null : a;
    t.etaTurn = isNaN(e) ? null : e;
    t.remain = (t.etaTurn != null && !isNaN(turn)) ? (t.etaTurn - turn) : null;
    t.isNear = t.remain != null && t.remain >= 0 && t.remain <= 5;
  });

  return {
    ok: true,
    // ── 头部常驻 ──
    turn: isNaN(turn) ? null : turn,
    chapter: isNaN(chapter) ? null : chapter,
    time: one('时间'),
    scene: one('场景'),
    // ── 此刻 NOW ──
    irreversible: parseIrr(F['不可逆']),
    summary: one('摘要'),
    present: parsePresent(F['在场']),
    // ── 档案 ARCHIVE ──
    relations: relations,
    relationsNow: relations.filter(r => r.isNow),
    threads: threads,
    threadsNear: threads.filter(t => t.isNear),
    infoGap: parseInfoGap(F['信息差']),
    offscreen: F['离线'] || null,
    // ── 角色 ──
    anchors: parseAnchors(A),
    // ── 同人（可选模块，没开就没有）──
    doujin: F['同人'] || null,
    canonDrift: one('原作偏离度'),
    meta: F['元知识'] || null,
    // ── 兜底：AI 自创字段（如 [角色动向] [角色年龄]）不丢弃 ──
    extras: (function () {
      const known = ['摘要', '章节', '回合', '时间', '场景', '在场', '离线',
        '信息差', '关系', '暗线', '同人', '元知识', '原作偏离度', '不可逆'];
      const o = {};
      Object.keys(F).forEach(k => { if (known.indexOf(k) < 0) o[k] = F[k]; });
      return Object.keys(o).length ? o : null;
    })()
  };
}

/* --------------------------------------------------------------------------
 * 4. 回溯采集（插件真正用的入口）
 *
 * 真实场景：AI 偶尔不吐 <state>（实测全职猎人 7 层里最后一层就没有），
 * 如果只看最新一层，面板会整片空白。所以要向上回溯最近一次有效输出。
 *
 * state 与 anchor 分开回溯：可能出现"最新层有 state 但没 anchor"。
 * 两者都记录来源楼层，不是最新层就标 stale，UI 上标灰注明来自哪一轮。
 * ------------------------------------------------------------------------ */
function collectFromChat(chat, opts) {
  opts = opts || {};
  const maxBack = opts.maxBack || 10;
  const list = Array.isArray(chat) ? chat : [];

  let stateHit = null, anchorHit = null;
  let scanned = 0;

  for (let i = list.length - 1; i >= 0 && scanned < maxBack; i--) {
    const m = list[i];
    if (!m || m.is_user || m.is_system) continue;
    scanned++;
    const mes = m.mes || '';
    if (!stateHit && extractBlock(mes, 'state'))  stateHit  = { i: i, raw: mes };
    if (!anchorHit && extractBlock(mes, 'anchor')) anchorHit = { i: i, raw: mes };
    if (stateHit && anchorHit) break;
  }

  // 合成：state 主体 + anchor（可能来自不同楼层）
  let base = null;
  if (stateHit) {
    base = collect(stateHit.raw);
  }
  if (!base || !base.ok) {
    return { ok: false, reason: 'no-state-block-in-recent-' + maxBack };
  }
  if (anchorHit && anchorHit.i !== stateHit.i) {
    const A = blockToFields(extractBlock(anchorHit.raw, 'anchor'));
    base.anchors = parseAnchors(A);
  }
  const latest = list.length - 1;
  base.stateFloor = stateHit.i;
  base.anchorFloor = anchorHit ? anchorHit.i : null;
  base.stale = stateHit.i !== latest;   // 非最新层 → UI 标灰"来自 R{N}"
  return base;
}




