/* ==========================================================
   真实楼层样本（实际脚本里由 getChatMessages(-1) 取）
   ========================================================== */
var SAMPLE=null;
var PRESET={name:"斯德哥尔摩症",version:"v1.9"};
var ITEMS=[];

/* ================= 真 API 桥 ================= */
function getApi(name){
  var sources=[
    {o:window},{o:pwin},
    {o:pwin.TavernHelper},{o:pwin.SillyTavern},
    {o:window.TavernHelper},{o:window.SillyTavern}
  ];
  for(var i=0;i<sources.length;i++){
    try{ var v=sources[i].o && sources[i].o[name];
      if(v!==undefined && v!==null) return {fn:v, owner:sources[i].o}; }catch(e){}
  }
  return null;
}
function call(name){
  var a=getApi(name); if(!a||typeof a.fn!=="function") return null;
  return {run:function(){ return a.fn.apply(a.owner, arguments); }, api:a};
}

/* 从当前预设读全部条目 */
function loadItems(){
  var c=call("getPreset"); if(!c) return false;
  var p; try{ p=c.run("in_use"); }catch(e){ return false; }
  if(!p||!p.prompts) return false;
  var ln=call("getLoadedPresetName");
  if(ln){ try{ var n=ln.run(); if(n) PRESET.name=n; }catch(e){} }
  /* 版本号写在预设名末尾（…v2.0）。这里内联解析，不调 presetVer —— 测试会把
     loadItems 单独抠出来 eval，依赖别的函数会直接崩。 */
  try{ var vm=String(PRESET.name||"").match(/v([0-9]+(?:[.][0-9]+)*) *$/i);
       if(vm) PRESET.version="v"+vm[1]; }catch(e){}
  /* ⚠ identifier 必须跟着走。
     酒馆靠 identifier==="chatHistory" 认「历史」条目、靠它索引排序表；
     ITEMS 里没有它，写回时就没法把改动贴回原条目，只能整体重建 —— 那就完了。 */
  ITEMS=p.prompts.map(function(x){
    var en=(x.enabled===undefined||x.enabled===null)?null:x.enabled;
    return {name:x.name||"", on:!!x.enabled, def:en,
            role:x.role||"system", content:x.content||"",
            identifier:(x.identifier===undefined||x.identifier===null)?"":String(x.identifier)};
  });
  return true;
}

/* 通道二（兜底）：SillyTavern 原生上下文的 chat 数组，字段是 mes / is_user */
function stChat(){
  try{
    var a=getApi("SillyTavern");
    var st=a && a.fn;
    if(st && typeof st.getContext==="function"){
      var ctx=st.getContext();
      if(ctx && Array.isArray(ctx.chat) && ctx.chat.length) return ctx.chat;
    }
  }catch(e){}
  return null;
}

var HOOK={
  /* 采集：读最新楼层的 <state> / <anchor>，向上回溯最多 10 层
     通道一：酒馆助手 getLastMessageId + getChatMessages（返回 Promise）
     通道二：SillyTavern.getContext().chat（同步兜底） */
  collect:function(cb){
    var gc=call("getChatMessages"), gl=call("getLastMessageId");

    function finish(all){
      var arr=[];
      try{
        arr=(all||[]).map(function(m){
          var mes=(m && m.message!==undefined && m.message!==null) ? m.message : (m && m.mes!==undefined ? m.mes : "");
          var isUser=(m && m.role) ? (m.role==="user") : !!(m && m.is_user);
          return {mes:String(mes||""), is_user:isUser};
        });
      }catch(e){ cb(null,"楼层数据格式异常："+e); return; }
      if(!arr.length){ cb(null,"当前对话还没有楼层"); return; }
      try{
        var r=collectFromChat(arr);
        if(!r||!r.ok){ cb(null,"没读到 <state>：AI 这一轮没输出状态块"); return; }
        cb(r,null);
      }catch(e){ cb(null,"解析失败："+e); }
    }

    function fallback(){
      var c=stChat();
      if(c) finish(c);
      else cb(null,"读不到聊天：酒馆助手与 SillyTavern 上下文都不可用");
    }

    if(!gc){ fallback(); return; }
    try{
      var p;
      if(gl){
        /* getLastMessageId 可能是 Promise 也可能是数字，统一按 Promise 处理 */
        p=Promise.resolve(gl.run()).then(function(id){
          var n=parseInt(id,10);
          var from=(isFinite(n)&&n>=0) ? Math.max(0,n-11) : 0;
          var to=(isFinite(n)&&n>=0) ? n : "lastMessageId";
          return gc.run(from+"-"+to);
        });
      }else{
        p=Promise.resolve(gc.run("0-{{lastMessageId}}"));
      }
      Promise.resolve(p).then(function(all){
        if(Array.isArray(all) && all.length) finish(all);
        else fallback();
      }, fallback);
    }catch(e){ fallback(); }
  },

  /* 写入：把条目列表的开关/改名/内容写回当前预设
     ⚠⚠ 只能「就地改字段」，绝不能整体重建 prompts。
        整体重建会丢掉 identifier / marker / system_prompt / injection_* / attach_*，
        后果：酒馆认不出 identifier==="chatHistory" 的历史条目，
        它退化成普通条目 —— 对话上下文不再发给 AI（血的教训 #12）。
        只写 name / role / content / enabled 四个用户真正会改的字段，
        其余一律沿用原条目对象。 */
  save:function(cb){
    var c=call("updatePresetWith");
    if(!c){ cb(false,"找不到 updatePresetWith"); return; }
    try{
      var n=0;
      var r=c.run("in_use", function(preset){
        var src=Array.isArray(preset.prompts)?preset.prompts:[];
        /* 原条目索引：优先按 identifier，退化按 name（老预设可能没 identifier） */
        var byId={}, byName={}, i;
        for(i=0;i<src.length;i++){
          var q=src[i]; if(!q) continue;
          if(q.identifier) byId[q.identifier]=q;
          if(q.name && byName[q.name]===undefined) byName[q.name]=q;
        }
        var out=[];
        for(i=0;i<ITEMS.length;i++){
          var it=ITEMS[i]; if(!it) continue;
          var base=(it.identifier && byId[it.identifier]) ||
                   (it.name && byName[it.name]) || null;
          if(!base){
            /* 新增条目：建最简结构，但仍带上 identifier（若已知） */
            var o={name:it.name, role:it.role, content:it.content};
            if(it.identifier) o.identifier=it.identifier;
            if(it.def!==null) o.enabled=!!it.on;
            out.push(o); continue;
          }
          base.name=it.name;
          base.role=it.role;
          base.content=it.content;
          if(it.def!==null) base.enabled=!!it.on;   /* 内置条目不动 enabled */
          out.push(base); n++;
        }
        preset.prompts=out;
        return preset;
      }, {render:"immediate"});
      var msg="已写入预设（"+n+" 条，保留原字段）";
      if(r && r.then) r.then(function(){cb(true,msg);},
                             function(e){cb(false,"写入失败："+e);});
      else cb(true,msg);
    }catch(e){ cb(false,"写入失败："+e); }
  },

  /* 自动采集：注册酒馆事件；没有事件系统就退化为轮询 lastMessageId */
  onNewMessage:function(cb){
    var ev=call("eventOn"), tv=getApi("tavern_events");
    if(ev){
      try{
        var t=(tv&&tv.fn)?tv.fn:({
          MESSAGE_RECEIVED:"message_received", MESSAGE_SENT:"message_sent",
          MESSAGE_SWIPED:"message_swiped",     MESSAGE_UPDATED:"message_updated",
          MESSAGE_DELETED:"message_deleted",   CHAT_CHANGED:"chat_id_changed"
        });
        var keys=["MESSAGE_RECEIVED","MESSAGE_SENT","MESSAGE_SWIPED",
                  "MESSAGE_UPDATED","MESSAGE_DELETED","CHAT_CHANGED"], n=0;
        keys.forEach(function(k){
          var name=t[k]; if(!name) return;
          try{ ev.run(name, function(){ cb(); }); n++; }catch(e){}
        });
        if(n) return "事件";
      }catch(e){}
    }
    /* 兜底：轮询楼层号，变了就采一次 */
    var gl=call("getLastMessageId");
    if(!gl) return "";
    var last=null;
    setInterval(function(){
      try{
        Promise.resolve(gl.run()).then(function(id){
          var m=parseInt(id,10);
          if(!isFinite(m)) return;
          if(last===null){ last=m; return; }
          if(m!==last){ last=m; cb(); }
        });
      }catch(e){}
    }, 4000);
    return "轮询";
  },

  /* 拉远端预设 JSON（只拉不算，先给用户看清单） */
  fetchPreset:function(url,cb){
    if(!url){ cb(false,null,"请先填仓库地址"); return; }
    fetch(url,{cache:"no-store"}).then(function(r){
      if(!r.ok) throw new Error("HTTP "+r.status+"（地址不对 / 文件被删 / 私有仓库）");
      return r.text();
    }).then(function(t){
      var j;
      try{ j=JSON.parse(t); }
      catch(e){ throw new Error("拉到的不是 JSON（大概是 404 网页或 GitHub 的 HTML 页面）"); }
      if(!j || !Array.isArray(j.prompts)) throw new Error("拉到的 JSON 里没有 prompts 数组，不像预设文件");
      cb(true,j,null);
    }).catch(function(e){ cb(false,null,(e&&e.message)||String(e)); });
  },

  /* 拉仓库索引 update.json */
  fetchManifest:function(url,cb){
    fetch(url,{cache:"no-store"}).then(function(r){
      if(!r.ok) throw new Error("HTTP "+r.status+"（地址不对 / 文件被删 / 私有仓库）");
      return r.text();
    }).then(function(t){
      var j;
      try{ j=JSON.parse(t); }
      catch(e){ throw new Error("update.json 不是合法 JSON（大概是 404 网页或 GitHub 的 HTML 页面）"); }
      if(!j || (!j.preset && !j.script))
        throw new Error("update.json 里既没有 preset 也没有 script（键名写错？）");
      cb(true,j,null);
    }).catch(function(e){ cb(false,null,(e&&e.message)||String(e)); });
  },

  /* 拉纯文本（脚本本体） */
  fetchText:function(url,cb){
    fetch(url,{cache:"no-store"}).then(function(r){
      if(!r.ok) throw new Error("HTTP "+r.status+"（地址不对 / 文件被删 / 私有仓库）");
      return r.text();
    }).then(function(t){
      if(!t || t.length<200) throw new Error("拉到的内容太短，不像完整脚本");
      cb(true,t,null);
    }).catch(function(e){ cb(false,null,(e&&e.message)||String(e)); });
  },

  /* 脚本本体整段替换：写回全局脚本库 + 当前预设里嵌的那份 */
  applyScript:function(text,cb){
    var c=call("updateScriptTreesWith");
    if(!c){ cb(false,"找不到 updateScriptTreesWith（酒馆助手版本太旧，请手动导入脚本文件）"); return; }
    var SNAME="斯德哥尔摩·状态球", hits={n:0};
    function clone(o){ var x={}, k;
      for(k in o) if(Object.prototype.hasOwnProperty.call(o,k)) x[k]=o[k];
      return x; }
    function one(s){
      if(!s || s.name!==SNAME) return s;
      hits.n++;
      var o=clone(s);
      o.content=text; o.enabled=true; o.type="script";
      return o;
    }
    function upd(trees){
      return (trees||[]).map(function(t){
        if(!t) return t;
        if(t.type==="folder"){ var o=clone(t); o.scripts=(t.scripts||[]).map(one); return o; }
        return one(t);
      });
    }
    try{
      var a=c.run(upd,{type:"global"});
      var b=c.run(upd,{type:"preset"});
      var done=function(){
        cb(true, hits.n ? ("脚本已更新（写入 "+hits.n+" 处），重开酒馆生效")
                        : ("脚本库里没找到「"+SNAME+"」，已跳过（可手动导入脚本文件）"));
      };
      if(a && a.then) a.then(function(){ return b; }).then(done, function(e){ cb(false,"脚本写入失败："+e); });
      else done();
    }catch(e){ cb(false,"脚本写入失败："+e); }
  },

  /* 合并计划：远端每条 → 是「更新已有」还是「新增」；本地多的 → 「保留」
     v1.6：只有「内容真的不一样」才算一条更新。以前只要名字对上就算更新，
     于是明明一模一样的预设也会报「更新 67 条」，看着像坏了 —— 现在这种情况
     会直接告诉你「预设没有变动」。 */
  plan:function(remote){
    var g=call("getPreset"); var local=null;
    try{ local=g?g.run("in_use"):null; }catch(e){}
    if(!local||!Array.isArray(local.prompts)) return null;
    var m=__skMaps(local.prompts), used={},
        st={upd:0,add:0,kept:0,renamed:0,toggle:0,rm:0,same:0,nochange:0,keptList:[]};
    var kill=__skKillSet(remote);
    (remote.prompts||[]).forEach(function(r){
      var i=__skFind(m,r);
      if(i>=0){
        used[i]=1;
        var lo=local.prompts[i];
        if(__skSameItem(lo,r)) st.same++; else st.upd++;
        if(lo.name && lo.name!==r.name) st.renamed++;
        if(lo.enabled!==undefined && lo.enabled!==null && (!!lo.enabled)!==(!!r.enabled)) st.toggle++;
      } else st.add++;
    });
    local.prompts.forEach(function(l,i){
      if(used[i]) return;
      if(__skIsKilled(kill,l)){ st.rm++; return; }   /* 补丁要删的 */
      st.kept++;
      st.keptList.push({id:(l.identifier||l.name||""),
                        name:(l.name||l.identifier||"(无名条目)")});
    });
    st.local=local.prompts.length;
    st.remote=(remote.prompts||[]).length;
    /* 一条要改的都没有（没更新 / 没新增 / 没删除）＝ 这版预设和你现在用的一模一样 */
    st.nochange=(!st.upd && !st.add && !st.rm)?1:0;
    return st;
  },

  /* 把「新版没有」的条目从当前预设里删掉（用户在清单里点了自己的清理按钮才走到这）。
     只删用户勾选的那几条，排序表里的残留一起清掉，其余字段照旧 —— 不整体重建 prompts。 */
  dropItems:function(ids, cb){
    var c=call("updatePresetWith");
    if(!c){ cb(false,"找不到 updatePresetWith（酒馆助手版本太旧）"); return; }
    var set={}; (ids||[]).forEach(function(x){ if(x) set[x]=1; });
    if(!Object.keys(set).length){ cb(false,"没有要清理的条目"); return; }
    var key={}, n=0;
    try{
      var g=call("getPreset"); var local=null;
      try{ local=g?g.run("in_use"):null; }catch(e){}
      if(!local||!Array.isArray(local.prompts)){ cb(false,"读不到当前预设条目"); return; }
      var hit=function(p){ return !!(set[p.identifier||""] || set[p.name||""]); };
      local.prompts.forEach(function(p){
        if(!hit(p)) return;
        n++; if(p.identifier) key[p.identifier]=1;
      });
      if(!n){ cb(false,"这些条目已经不在当前预设里了"); return; }
      var w=c.run("in_use", function(preset){
        preset.prompts=(preset.prompts||[]).filter(function(p){
          if(p.identifier && key[p.identifier]) return false;
          if(!p.identifier && set[p.name||""]) return false;
          return true;
        });
        (preset.prompt_order||[]).forEach(function(bk){
          if(!Array.isArray(bk.order)) return;
          bk.order=bk.order.filter(function(o){
            return !(o && o.identifier && key[o.identifier]);
          });
        });
        return preset;
      }, {render:"immediate"});
      var done=function(){
        cb(true, "已从预设里移除 "+n+" 条");
      };
      if(w&&w.then) w.then(done, function(e){ cb(false,"写入失败："+e); });
      else done();
    }catch(e){ cb(false,"清理失败："+e); }
  },

  /* 应用：按条目合并后写回，不整体覆盖 */
  apply:function(remote,cb){
    var c=call("updatePresetWith");
    if(!c){ cb(false,"找不到 updatePresetWith（酒馆助手版本太旧）"); return; }
    var g=call("getPreset"); var local=null;
    try{ local=g?g.run("in_use"):null; }catch(e){}
    if(!local||!Array.isArray(local.prompts)){ cb(false,"读不到当前预设条目"); return; }
    try{
      var r=__skMerge(remote, local);
      var w=c.run("in_use", function(preset){
        /* 1) 其它顶层字段跟着远端走（采样参数等），但预设名保留本地的 */
        Object.keys(remote).forEach(function(k){
          if(k==="prompts"||k==="prompt_order"||k==="name") return;
          if(k==="extensions"){
            /* 扩展逐键合并：远端的优先，但 tavern_helper（本脚本）强制保留本地，
               否则仓库里没带脚本就会把悬浮球从预设里删掉 */
            var le=preset.extensions||{}, re=remote.extensions||{}, mx={};
            Object.keys(re).forEach(function(x){ mx[x]=re[x]; });
            Object.keys(le).forEach(function(x){ if(mx[x]===undefined) mx[x]=le[x]; });
            mx.tavern_helper = le.tavern_helper || mx.tavern_helper;
            preset.extensions = mx;
            return;
          }
          preset[k]=remote[k];
        });
        /* 2) 条目：远端顺序为准，匹配上的用远端内容、保留你的开关与改名，本地独有的追到末尾 */
        preset.prompts = r.prompts;
        /* 3) 排序表：远端顺序 + 本地自定义条目补在后面 */
        if(r.order) preset.prompt_order = r.order;
        return preset;
      }, {render:"immediate"});
      /* v2.0：updatePresetWith 返回的就是「更新后的预设」（官方文档保证）。
         以前写完之后又调 getPreset 重读一遍来刷新面板 —— 读回来的是旧的，
         界面自然也是旧的（酒馆自己的界面是新的，两边读的不是同一份东西）。
         现在直接用这个返回值；重读只在拿不到返回值时兜底。 */
      var done=function(np){
        if(remote.name) PRESET.version=remote.name;
        var items=__skItemsOf(np) || __skItemsOf(r.prompts);
        cb(true, "已合并更新："+r.st.upd+" 条更新 / "+r.st.add+" 条新增 / "+r.st.kept+" 条新版没有"
                + (r.st.rm ? (" / "+r.st.rm+" 条删除") : ""), items);
      };
      if(w&&w.then) w.then(done, function(e){ cb(false,"写入失败："+e); });
      else done(null);
    }catch(e){ cb(false,"合并失败："+e); }
  }
};

/* ── 合并工具 ──────────────────────────────────────────────
   条目身份：优先 identifier（稳定 slug），退回 name（作者改了 identifier 时也能对上）
   规则：匹配上 → 内容/角色用远端（这才是"更新"），开关与改名保留本地
        远端多出来 → 直接新增
        本地多出来 → 原样保留，排在最后（这就是你自己的自定义条目） */
/* v2.0：把「预设对象」或「原始条目数组」转成面板用的 ITEMS 结构。
   写入成功后拿它直接刷新面板，省掉一次重读（重读可能读到旧的）。 */
function __skItemsOf(p){
  var arr = (!p) ? null : (Array.isArray(p) ? p : (Array.isArray(p.prompts) ? p.prompts : null));
  if(!arr || !arr.length) return null;
  return arr.map(function(x){
    var en=(x.enabled===undefined||x.enabled===null)?null:x.enabled;
    return {name:x.name||"", on:!!x.enabled, def:en,
            role:x.role||"system", content:x.content||"",
            identifier:(x.identifier===undefined||x.identifier===null)?"":String(x.identifier)};
  });
}
function __skKey(p){ return (p && (p.identifier || p.name)) || ""; }
function __skMaps(lp){
  var byId={}, byName={};
  for(var i=0;i<lp.length;i++){
    var k=__skKey(lp[i]);
    if(k && byId[k]===undefined) byId[k]=i;
    if(lp[i].name && byName[lp[i].name]===undefined) byName[lp[i].name]=i;
  }
  return {byId:byId, byName:byName};
}
function __skFind(m, r){
  var k=__skKey(r);
  if(k && m.byId[k]!==undefined) return m.byId[k];
  if(r.name && m.byName[r.name]!==undefined) return m.byName[r.name];
  return -1;
}
/* 两条是不是「实质一样」：只比会真正影响 AI 收到什么的字段。
   开关（enabled）和你改过的名字不算差异 —— 那是你自己的设置，不该被当成「需要更新」。 */
var __SK_SAME_KEYS=["content","role","marker","system_prompt","injection_position",
  "injection_depth","injection_order","injection_trigger","forbid_overrides","extension"];
function __skSameItem(lo, r){
  var i,k,a,b;
  for(i=0;i<__SK_SAME_KEYS.length;i++){
    k=__SK_SAME_KEYS[i];
    a=lo[k]; b=r[k];
    if(a===undefined) a=null;
    if(b===undefined) b=null;
    if(b===null) continue;        /* 远端这条没写这个字段 → 合并时从本地继承，等于没变 */
    if(a===null) return false;    /* 本地没有、远端有 → 会补进去，算一条变化 */
    if(typeof a==="object" || typeof b==="object"){
      if(JSON.stringify(a)!==JSON.stringify(b)) return false;
      continue;
    }
    if(String(a)!==String(b)) return false;
  }
  return true;
}
/* 补丁里的 remove：可以是字符串（identifier 或 name），也可以是 {identifier:..} / {name:..} */
function __skKillSet(remote){
  var s={};
  (remote.remove||[]).forEach(function(x){
    if(typeof x==="string"){ if(x) s[x]=1; }
    else if(x && typeof x==="object"){ if(x.identifier) s[x.identifier]=1; if(x.name) s[x.name]=1; }
  });
  return s;
}
function __skIsKilled(kill, it){
  if(!kill || (!kill[it.identifier||""] && !kill[it.name||""])) return false;
  return true;
}
function __skMerge(remote, local){
  var rp=remote.prompts||[], lp=local.prompts||[];
  var m=__skMaps(lp), used={}, out=[], kill=__skKillSet(remote);
  var st={upd:0,add:0,kept:0,rm:0};
  rp.forEach(function(r){
    var i=__skFind(m,r);
    var it=JSON.parse(JSON.stringify(r));
    if(i>=0){
      used[i]=1;
      var lo=lp[i];
      /* 增量补丁可能只写了 content/name 一两个字段，
         缺的字段（role / 注入位置 / marker 等）必须从本地继承，否则条目会失效 */
      Object.keys(lo).forEach(function(k){ if(it[k]===undefined || it[k]===null) it[k]=lo[k]; });
      if(lo.name && lo.name!==r.name) it.name=lo.name;      /* 保留你的改名 */
      if(lo.enabled!==undefined && lo.enabled!==null) it.enabled=lo.enabled;  /* 保留你的开关 */
      if(!it.identifier && lo.identifier) it.identifier=lo.identifier;
      st.upd++;
    } else st.add++;
    if(__skIsKilled(kill,it)) return;                        /* 同一份补丁里又被 remove 了 */
    out.push(it);
  });
  lp.forEach(function(l,i){
    if(used[i]) return;
    if(__skIsKilled(kill,l)){ st.rm++; return; }             /* 补丁明确要删的条目 */
    out.push(JSON.parse(JSON.stringify(l))); st.kept++;
  });

  /* rename：只改名不换正文（from 可以写 identifier 也可以写名字）
     注意：你在本地改过的名字会覆盖这个改名 —— 那是你的东西，不抢 */
  (remote.rename||[]).forEach(function(rn){
    if(!rn||!rn.from||!rn.to) return;
    out.forEach(function(it){
      if(it.identifier===rn.from || it.name===rn.from) it.name=rn.to;
    });
  });

  /* 排序表：远端有就照远端，然后把你自定义的 identifier 补进每个 block 的末尾 */
  var order=null;
  if(Array.isArray(remote.order) && remote.order.length){
    /* 补丁给了完整顺序：按它重排，没提到的排后面（与 tools/ai_patch.py 行为一致） */
    var have={}; out.forEach(function(it){ if(it.identifier) have[it.identifier]=it; });
    var seq=[]; remote.order.forEach(function(id){ if(have[id]) seq.push(id); });
    out.forEach(function(it){ if(it.identifier && seq.indexOf(it.identifier)<0) seq.push(it.identifier); });
    var blocks=(Array.isArray(remote.prompt_order)&&remote.prompt_order.length)?remote.prompt_order:local.prompt_order;
    order=(blocks||[]).map(function(b){
      return {character_id:(b&&b.character_id!==undefined)?b.character_id:100001,
              order:seq.map(function(id){
                return {enabled:!!have[id].enabled, identifier:id};})};
    });
  }else if(Array.isArray(remote.prompt_order) && remote.prompt_order.length){
    order=JSON.parse(JSON.stringify(remote.prompt_order));
    var inOrder={};
    order.forEach(function(b){ (b.order||[]).forEach(function(o){ if(o&&o.identifier) inOrder[o.identifier]=1; }); });
    var extra=out.filter(function(it){ return it.identifier && !inOrder[it.identifier]; });
    order.forEach(function(b){
      if(!Array.isArray(b.order)) b.order=[];
      /* 被补丁删掉的 identifier 也从排序表里去掉 */
      b.order=b.order.filter(function(o){ return !(o&&o.identifier&&kill[o.identifier]); });
      extra.forEach(function(it){ b.order.push({enabled:!!it.enabled, identifier:it.identifier}); });
    });
  } else if(Array.isArray(local.prompt_order) && local.prompt_order.length && (st.add || st.rm)){
    /* 增量补丁没带排序表，但新增或删除了条目：
       必须照本地排序表整理一份 —— 新条目要补进去（否则酒馆里看不到），
       被删的 identifier 要清掉（否则它会一直残留在排序表里）。 */
    order=JSON.parse(JSON.stringify(local.prompt_order));
    var seen={};
    order.forEach(function(b){ (b.order||[]).forEach(function(o){ if(o&&o.identifier) seen[o.identifier]=1; }); });
    order.forEach(function(b){
      if(!Array.isArray(b.order)) b.order=[];
      b.order=b.order.filter(function(o){ return !(o&&o.identifier&&kill[o.identifier]); });
      out.forEach(function(it){
        if(it.identifier && !seen[it.identifier]){
          seen[it.identifier]=1;
          b.order.push({enabled:!!it.enabled, identifier:it.identifier});
        }
      });
    });
  }
  return {prompts:out, order:order, st:st};
}

