function gOrder(){
  var a=GROUP_DEF.map(function(g){return {id:g.id,nm:g.nm,mine:0};});
  (GUSER.extra||[]).forEach(function(g){ a.push({id:g.id,nm:g.nm,mine:1}); });
  a.push({id:"__none",nm:"未分组",mine:0});
  return a;
}
function gOf(name){
