    h+=fold('f-gap','信息差 / 离线',(gap.length+off.length)+' 条',b2);}

  /* ── 三级（折叠）：角色档案（角色锚）── */
  var an=(d.anchors||[]);
  if(an.length){
    var b3="";
    an.forEach(function(a){
      var v=(a.affection===undefined||a.affection===null)?null:a.affection;
      b3+='<div class="anch">'
        +'<div class="ah"><span class="who">'+esc(a.name)+'</span>'
        +(a.age?'<span class="ag">'+esc(a.age)+'</span>':'')
        +(v===null?'':'<span class="aff '+(v>0?'pos':(v<0?'neg':''))+'">'+(v>0?'+':'')+v+'</span>')
        +'</div>'
        +(a.position?'<div class="ap">'+esc(a.position)+'</div>':'')
        +'<div class="kv">'
        +(a.desire?'<span><i>欲</i>'+esc(a.desire)+'</span>':'')
        +(a.fear?'<span><i>惧</i>'+esc(a.fear)+'</span>':'')
        +(a.line?'<span><i>线</i>'+esc(a.line)+'</span>':'')
        +(a.lie?'<span><i>装</i>'+esc(a.lie)+'</span>':'')
        +'</div>'
        +(a.viewOfUser?'<div class="av">'+esc(a.viewOfUser)+'</div>':'')
        +'</div>';});
    h+=fold('f-anch','角色档案',an.length+' 人',b3);}

  z.innerHTML=h;
  /* 折叠交互 */
  z.querySelectorAll(".fold-hd").forEach(function(el){
    el.onclick=function(){ el.parentNode.classList.toggle("open"); };});
