/* 视口：脚本跑在酒馆助手的小 iframe 里，UI 却挂在主窗口 ——
   凡是 innerWidth/innerHeight 一律取主窗口的，取 iframe 自己的会把面板钳到角落 */
function vpWin(){
  /* 打包到酒馆后，脚本里已经有一个指向主窗口的 pwin（见挂载那段）；
     预览页里没有 pwin，就用 window 自己 */
  try{ if(typeof pwin!=="undefined" && pwin && pwin!==window && pwin.document) return pwin; }catch(e){}
  /* 千万别写成 xx.Q( —— 构建会把 Q( 替换掉 */
  try{
    var pd = (window.parent && window.parent!==window) ? window.parent.document : null;
    if(pd && pd.getElementById("sk-orb-host")) return window.parent;
  }catch(e){}
  return window;
}

/* 是不是触屏：手机上「拖动」会被浏览器当成滚动，所以滚动区要让给滚动 */
var ISTOUCH=(function(){
  try{ return ('ontouchstart' in window) || ((navigator.maxTouchPoints||0)>0); }catch(e){ return false; }
})();

/* 拖动：球 & 面板（位置记在 localStorage） */
function dragInit(){
  var orbEl=Q("orb"), panelEl=Q("panel");
  var bar=panelEl.querySelector(".bar");
  function bind(handle, el, key, noDrag, big){
    var sx=0, sy=0, ox=0, oy=0, moved=false, on=false;
    handle.addEventListener("pointerdown", function(e){ if(on) return;
      if(noDrag && noDrag(e)) return;
      var r=el.getBoundingClientRect();
      sx=e.clientX; sy=e.clientY; ox=r.left; oy=r.top; moved=false; on=true;
      el.style.left=ox+"px"; el.style.top=oy+"px";
      el.style.right="auto"; el.style.bottom="auto";
      try{handle.setPointerCapture(e.pointerId);}catch(_){}
      e.preventDefault();
    });
    handle.addEventListener("pointermove", function(e){
      if(!on) return;
      var dx=e.clientX-sx, dy=e.clientY-sy;
      if(!moved && Math.abs(dx)+Math.abs(dy)<5) return;
      moved=true;
      var W=vpWin(), nx, ny;
      if(big){  /* 面板：允许拖到只露出一条边，但不会整块飞出屏幕 */
        var w=el.offsetWidth||430;
        nx=Math.max(80-w, Math.min(ox+dx, W.innerWidth-80));
        ny=Math.max(0,    Math.min(oy+dy, W.innerHeight-60));
      } else {
        nx=Math.max(0, Math.min(ox+dx, W.innerWidth-60));
        ny=Math.max(0, Math.min(oy+dy, W.innerHeight-60));
      }
      el.style.left=nx+"px"; el.style.top=ny+"px";
    });
    handle.addEventListener("pointerup", function(e){
      if(!on) return;
      on=false;
      try{handle.releasePointerCapture(e.pointerId);}catch(_){}
      if(moved){
        if(el.id==="orb") orbSnap(el);      /* 只有球会贴边吸附，面板不吸 */
        try{ localStorage.setItem(key, Math.round(parseFloat(el.style.left||0))+","+Math.round(parseFloat(el.style.top||0))); }catch(_){}
        /* 位置已经写进 localStorage，下次打开 panelNear() 会用 */
        /* 拖完这一次不要触发点击 */
        el.__justDragged=true;
        setTimeout(function(){ el.__justDragged=false; }, 50);
      }
    });
  }
  bind(orbEl, orbEl, "sk_orb_pos", null);
  /* 标题栏：手机上也能拖（CSS 里给了 touch-action:none，不然会被吃掉变成滚页面） */
  if(bar) bind(bar, panelEl, "sk_panel_pos", function(e){
    return !!(e.target && e.target.closest && e.target.closest("button"));
  }, true);
  /* 双击标题栏空白处＝面板回到正中（手机上没有双击手势之外的复位入口，这个最好找） */
  if(bar) bar.addEventListener("dblclick", function(e){
    if(e.target && e.target.closest && e.target.closest("button")) return;
    panelReset();
  });
  /* 整块面板随便拖：避开所有要点的东西
     ⚠ v1.7 修的硬伤：pointerdown 里的 preventDefault() 会把后面的 click 一起吃掉，
       所以凡是「点了要有反应」的东西都必须在这儿豁免，否则点击静默失效。
       以前漏了 .gh（组头）→ 电脑上点组头只是启动拖面板，折叠永远不触发；
       手机上因为 .scroll/#list 整块豁免反而没事，所以只在电脑上复现。
       现在内容区（列表 / 弹窗 / 编辑区）整块让出去，不再分设备。 */
  bind(panelEl, panelEl, "sk_panel_pos", function(e){
    var t=e.target;
    if(!t || !t.closest) return false;
    if(t.closest(".bar")) return true;   /* 标题栏交给上面那条 */
    /* 滚得动、点得动的地方，一律不抢 */
    if(t.closest(".scroll,#list,.dlg,.ed-body")) return true;
    if(t.closest("button,input,textarea,select,a,.sw,.gh,[data-gh],[data-hd],.fold-hd,"
                 +".sum,.avframe,.avc,.chip,.filt span,.vhd,.hero")) return true;
    return false;
  }, true);
  /* 恢复位置；跑出屏幕（或整个藏到边外太多）就丢掉，回到右下角默认位 */
  try{
    var p=localStorage.getItem("sk_orb_pos"), W1=vpWin();
    var w0=orbEl.offsetWidth||44, h0=orbEl.offsetHeight||44;
    if(p){ var a=p.split(","), L=parseFloat(a[0]), T=parseFloat(a[1]);
      var ed=""; try{ ed=localStorage.getItem("sk_orb_edge")||""; }catch(_){}
      /* 贴边时 left 可以是负的（藏 1/3 出去），所以上下限放宽一个球的宽度 */
      if(isFinite(L) && isFinite(T) && L>=-w0 && T>=0
         && L<=W1.innerWidth-w0/3 && T<=W1.innerHeight-h0/2){
        orbPlace(orbEl, L, T, (ed==="l"||ed==="r")?ed:"");
      } else { try{ localStorage.removeItem("sk_orb_pos"); }catch(_){} }
    }
  }catch(_){}
}

/* ---- 悬浮球贴边吸附 ----
   拖到离左右边缘很近时，把球吸过去：1/3 藏到屏幕外，整体变淡（.edge）。
   指针靠上去会浮出来一点，点它照常开面板。方向记在 localStorage，重开还在原位。 */
function orbSnap(el){
  var W=vpWin(), w=el.offsetWidth||44, h=el.offsetHeight||44;
  var L=parseFloat(el.style.left||0), T=parseFloat(el.style.top||0);
  var hide=Math.round(w/3);            /* 藏出去的那部分 ≈ 三分之一 */
  var zone=Math.max(56, Math.round(w*1.5));   /* 离边这么近就算「想贴边」 */
  var side="";
  if(L<=zone && L<=(W.innerWidth-(L+w))){ side="l"; L=-hide; }
  else if((W.innerWidth-(L+w))<=zone){ side="r"; L=W.innerWidth-w+hide; }
  T=Math.max(6, Math.min(T, W.innerHeight-h-6));
  orbPlace(el, L, T, side);
  return side;
}
function orbPlace(el, L, T, side){
  el.classList.add("snapping");        /* 给一次位移动画，别瞬移 */
  el.style.left=Math.round(L)+"px"; el.style.top=Math.round(T)+"px";
  el.style.right="auto"; el.style.bottom="auto";
  el.classList.toggle("edge", !!side);
  if(side) el.setAttribute("data-e", side); else el.removeAttribute("data-e");
  try{ localStorage.setItem("sk_orb_edge", side||""); }catch(_){}
  setTimeout(function(){ el.classList.remove("snapping"); }, 320);
}
function panelNear(){
  var panelEl=Q("panel");
  /* 用户存过位置就用；但如果那个位置已经跑到屏幕外（换显示器/缩窗口），别照搬，重新居中 */
  try{
    var p=localStorage.getItem("sk_panel_pos"), W0=vpWin();
    if(p){ var a=p.split(","), L=parseFloat(a[0]), T=parseFloat(a[1]);
      if(isFinite(L) && isFinite(T) && L>=0 && T>=0
         && L<=W0.innerWidth-80 && T<=W0.innerHeight-80){
        panelEl.style.left=L+"px"; panelEl.style.top=T+"px";
        panelEl.style.right="auto"; panelEl.style.bottom="auto"; return;
      }
    }
  }catch(_){}
  /* 默认：主窗口正中 */
  var W=vpWin();
  var w=panelEl.offsetWidth||430, hh=panelEl.offsetHeight||620;
  var left=Math.max(8, Math.round((W.innerWidth-w)/2));
  var top=Math.max(8, Math.round((W.innerHeight-hh)/2));
  panelEl.style.left=left+"px"; panelEl.style.top=top+"px";
  panelEl.style.right="auto"; panelEl.style.bottom="auto";
}

/* ========================================================== 条目列表（v1.3 分组版）
   ⚠ 分组只影响「怎么显示」：ITEMS 数组本身不重排，写回预设的顺序因此不变。 */
function renderList(){
  var z=Q("list"),h="",n=0;
  var filtering = (filter!=="all"||!!keyword);
  var gs = gOrder(), bucket={};
  gs.forEach(function(g){ bucket[g.id]=[]; });
  ITEMS.forEach(function(it,i){
    if(filter==="on"  && !isOn(it)) return;
    if(filter==="def" && !(it.def===true)) return;
    if(filter==="mod" && !isMod(it)) return;
    if(keyword && it.name.toLowerCase().indexOf(keyword.toLowerCase())<0) return;
    var gid=gOf(it.name);
    if(!bucket[gid]) bucket[gid]=[];
    bucket[gid].push(i); n++;
  });

  gs.forEach(function(g){
    var arr=bucket[g.id]||[];
    /* 空组：你自己建的组照常显示（好往里加东西），默认组就不占位了 */
    if(!arr.length && !g.mine) return;
    var open = filtering ? true : gIsOpen(g.id);
    var on=0; arr.forEach(function(i){ if(isOn(ITEMS[i])) on++; });
    var pct = arr.length ? Math.round(on/arr.length*100) : 0;
    h+='<div class="gh'+(open?' open':'')+'" data-gh="'+esc(g.id)+'">'
      + '<span class="cv">▶</span>'
      + '<span class="nm">'+esc(g.nm)+'</span>'
      + '<span class="gb"><i style="width:'+pct+'%"></i></span>'
      + '<span class="ct">'+on+'/'+arr.length+'</span>'
      + '</div>';
    arr.forEach(function(i){
      var it=ITEMS[i];
      var slot = (it.def===null||it.def===undefined);
      h+='<div class="row'+(isOn(it)?'':' off')+(slot?' slot':'')
        + (it.def===true?' def':'')+(open?'':' gHidden')+'" data-i="'+i+'" data-g="'+esc(g.id)+'">'
        + '<span class="hdle" data-hd="'+i+'" title="按住拖动排序（组内）">'+icon('drag','sm')+'</span>'
        + '<span class="sw'+(isOn(it)?' on':'')+(slot?' dis':'')+'" data-sw="'+i+'"></span>'
        + '<span class="nm">'+esc(it.name)+'</span>';
      if(slot) h+='<span class="bg">槽位</span>';
      else if(!it.content) h+='<span class="bg">占位</span>';
      if(it.def===true) h+='<span class="bg def">默认开</span>';
      if(isMod(it)) h+='<span class="bg mod">已改</span>';
      h+= '<span class="op"><button data-ed="'+i+'" title="编辑">'+icon('edit','sm')+'</button></span></div>';
    });
  });

  z.innerHTML = n ? h : '<div class="empty">'+icon('empty')+'没有匹配的条目</div>';

  z.querySelectorAll("[data-gh]").forEach(function(el){
    el.onclick=function(){
      var id=el.dataset.gh;
      GUSER.open[id]=!gIsOpen(id); gSave(); renderList();
    };});
  z.querySelectorAll("[data-sw]").forEach(function(el){
    el.onclick=function(){
      if(locked){toast("已锁定，先点锁形按钮解锁");return;}
      var it=ITEMS[+el.dataset.sw];
      if(it.def===null||it.def===undefined){toast("酒馆固定槽位，不能关闭");return;}
      it.on=!it.on; renderList(); updFoot();
    };});
  z.querySelectorAll("[data-ed]").forEach(function(el){
    el.onclick=function(){openEditor(+el.dataset.ed);};});
  bindDrag(z);
}

/* ========================================================== 拖拽排序 */
var drag=null;
function bindDrag(z){
  z.querySelectorAll("[data-hd]").forEach(function(el){
    el.addEventListener("pointerdown", function(e){
      if(locked){toast("已锁定，不能拖动");return;}
      /* 安全：筛选/搜索状态下 DOM 只是子集，重排会丢失未显示的条目 */
      if(filter!=="all"||keyword){
        toast('请先切到「全部」并清空搜索，再拖动排序');return;}
      var row=el.closest(".row");
      if(!row) return;
      e.preventDefault();
      /* v1.3：拖动只在「同一组内」重排。跨组不动，保证别的组顺序纹丝不动 */
      var gid=row.dataset.g||"", slots=[];
      ITEMS.forEach(function(it,k){ if(gOf(it.name)===gid) slots.push(k); });
      drag={row:row,idx:+row.dataset.i,g:gid,old:ITEMS.slice(),slots:slots};
      row.classList.add("dragging");
      host.style.userSelect="none";
      root.addEventListener("pointermove",onDragMove);
      root.addEventListener("pointerup",onDragUp);
    });
  });
}
function onDragMove(e){
  if(!drag) return;
  var y=e.clientY;
  var rows=Array.from(root.querySelectorAll('#list .row[data-g="'+drag.g+'"]:not(.dragging)'));
  var target=null;
  for(var i=0;i<rows.length;i++){
    var rc=rows[i].getBoundingClientRect();
    if(y < rc.top + rc.height/2){ target=rows[i]; break; }
  }
  if(target) Q("list").insertBefore(drag.row, target);
  else {
    /* 落到本组最后一条后面：找同组最后一条，插到它后面 */
    var last=rows.length?rows[rows.length-1]:null;
    if(last && last.nextSibling) Q("list").insertBefore(drag.row, last.nextSibling);
    else Q("list").appendChild(drag.row);
  }
}
function onDragUp(){
  if(!drag) return;
  drag.row.classList.remove("dragging");
  host.style.userSelect="";
  document.removeEventListener("pointermove",onDragMove);
  document.removeEventListener("pointerup",onDragUp);
  /* v1.3：只把本组的新顺序回填到本组原来占的位置上，
     其余条目的位置一个都不动（ITEMS 长度与跨组顺序完全不变） */
  var OLD=drag.old, slots=drag.slots;
  var order=Array.from(root.querySelectorAll('#list .row[data-g="'+drag.g+'"]'))
              .map(function(r){return +r.dataset.i;});
  var changed = order.length===slots.length &&
                order.some(function(v,k){return v!==slots[k];});
  if(changed){
    slots.forEach(function(s,k){ ITEMS[s]=OLD[order[k]]; });
    toast("顺序已调整（组内）");
  }
  renderList(); updFoot();
  drag=null;
}

/* ========================================================== 锁定 */
var locked=false;
function setLock(v){
  locked=v;
  var b=Q("btnLock");
  b.innerHTML=icon(v?"lock":"unlock","sm");
  b.title=v?"已锁定（开关与排序已禁用，点此解锁）":"未锁定（可拖动排序 / 切换开关）";
  b.classList.toggle("on",v);
  Q("list").classList.toggle("locked",v);
  try{localStorage.setItem("sk_orb_lock",v?"1":"0");}catch(e){}
}

function updFoot(){
  var on=ITEMS.filter(isOn).length, mod=ITEMS.filter(isMod).length;
  Q("footSt").innerHTML =
    "<b>"+on+" / "+ITEMS.length+"</b> 条开启" + (mod? ' · <b>'+mod+'</b> 条已改动':'');
  Q("sub").textContent =
    PRESET.version+" · "+ITEMS.length+" 条";
}

/* ========================================================== 编辑器 */
var ed=Q("editor");
function openEditor(i){
  editing = (i===null||i===undefined) ? {name:"新条目",content:"",role:"system",on:true,def:false,isNew:true} : ITEMS[i];
  editing._i = (i===null||i===undefined) ? -1 : i;
  Q("edTitle").textContent = editing.isNew ? "新增条目" : "编辑条目";
  Q("edName").value = editing.name;
  Q("edRole").value = editing.role || "system";
  Q("edBody").value = editing.content || "";
  editing._oldName = editing.name;
  /* 分组下拉：当前所在组 + 全部组 + 新建 */
  var gs=Q("edGrp");
  if(gs){
    var cur=gOf(editing.name);
    gs.innerHTML="";
    gOrder().forEach(function(g){
      var o=document.createElement("option");
      o.value=g.id; o.textContent=g.nm;
      if(g.id===cur) o.selected=true;
      gs.appendChild(o);
    });
    var o2=document.createElement("option");
    o2.value="__new"; o2.textContent="＋ 新建分组…";
    gs.appendChild(o2);
    gs._old=cur;
  }
  var slot=(editing.def===null||editing.def===undefined);
  Q("edDelWrap").style.display =
    (editing.isNew || slot) ? "none" : "block";
  ed.classList.add("on");
  if(editing.isNew) Q("edName").select();
}
function closeEditor(){ed.classList.remove("on");editing=null;}
Q("edCancel").onclick=closeEditor;
Q("edDel").onclick=function(){
  if(!editing||editing._i<0) return;
  var it=ITEMS[editing._i];
  if(confirm('删除条目「'+it.name+'」？
删除后无法撤销（演示环境不写盘）。')){
    ITEMS.splice(editing._i,1);closeEditor();renderList();updFoot();toast("已删除（未写盘）");}
};
Q("edSave").onclick=function(){
  if(!editing) return;
  var nm=Q("edName").value.trim();
  if(!nm){toast("条目名不能为空");return;}
  editing.name=nm;
  editing.role=Q("edRole").value;
  editing.content=Q("edBody").value;
  /* 分组：只记在脚本自己的覆盖表里，不写进预设条目 */
  var gs=Q("edGrp");
  if(gs){
    var gid=gs.value;
    if(gid==="__new"){
      var gn=prompt("新分组的名字：","我的分组");
      gid=gNew(gn);
      if(!gid) gid=gs._old||"__none";
    }
    if(editing._oldName && editing._oldName!==nm && GUSER.map[editing._oldName])
      delete GUSER.map[editing._oldName];
    gMove(nm,gid);
  }
  if(editing.isNew){delete editing.isNew;ITEMS.unshift(editing);}
  closeEditor(); renderList(); updFoot(); toast("已保存「"+nm+"」");
};

Q("btnAdd").onclick=function(){openEditor(null);};
/* 分组管理：新建组 / 全部展开 / 全部折叠 */
