/* ========================================================== 在线更新（预设 / 脚本 两条通道分开）
   仓库只要一个入口：填「仓库根地址」，脚本自己去拼 <根>/update.json
   update.json 长这样（缺哪条通道就只更新另一条）：
   {
     "preset": {"version":"v1.9","file":"preset/斯德哥尔摩症_v1.9.json","changelog":["…"]},
     "script": {"version":"v1.0","file":"script/斯德哥尔摩·状态球.js","changelog":["…"]}
   }                                                                        */
var ORB_VER="v2.1";                 /* ← 本脚本自己的版本号，改这里＝改版本 */
var REMOTE = {
  base:"https://raw.githubusercontent.com/zhaoyichan/SillyTavern-Preset-Stockholm/main",
  mf:null,          /* 索引 */
  preset:null,      /* 远端预设 JSON */
  script:null,      /* 远端脚本文本 */
  want:{preset:true, script:true},
  have:{preset:true, script:true},   /* 仓库这次提供了哪几条通道（缺哪条就灰掉） */
  touched:false,                     /* 用户在弹窗里手动动过勾选吗（动过就听他的） */
  hist:[],                           /* update.json 里的 history：全部历史版本（最新在上） */
  sel:null,                          /* 用户选中要更新的那一版（null＝没走版本列表） */
  ahead:null,                        /* 本地比仓库还新的那几条（v1.7：「关于」里显示，不弹窗） */
  remote:{preset:"", script:""},     /* 最近一次查到的仓库版本 */
  pv:"", sv:"", plogs:[], slogs:[], plan:null
};
var mask=Q("mask"), dlg=Q("dlg");

function normBase(u){
  u=(u||"").trim().replace(//+$/,"");
  if(/update\.json$/i.test(u)) u=u.replace(/update\.json$/i,"");
  return u;
}
function joinUrl(b,f){
  b=normBase(b); if(!b) return "";
  if(/^https?:///i.test(f||"")) return f;
  /* 逐段编码：中文文件名不编码会拼出非法地址，raw 直接 404 */
  return b+"/"+String(f||"").replace(/^/+/,"").split("/").map(encodeURIComponent).join("/");
}
/* 老用法兼容：直接贴了某个 .json 的完整地址 → 当预设文件用 */
function isLegacyPresetUrl(u){
  var s=(u||"").trim();
  return /\.json$/i.test(s) && !/update\.json$/i.test(s);
}
function chanRow(key,title,desc,cur){
  var on=!!REMOTE.want[key], ok=!!REMOTE.have[key];
  if(!ok) return '<div class="chan na" data-c="'+key+'">'
    +'<span class="cbx"></span>'
    +'<div class="cx"><b>'+esc(title)+'</b><span>仓库这次没提供，跳过</span></div>'
    +'<em>未提供</em></div>';
  return '<div class="chan'+(on?" on":"")+'" data-c="'+key+'">'
    +'<span class="cbx"></span>'
    +'<div class="cx"><b>'+esc(title)+'</b><span>'+esc(desc)+'</span></div>'
    +'<em>'+esc(cur||"？")+'</em></div>';
}

/* ---- 本地导入：不用联网，直接选文件装 ----
   预设文件：酒馆导出的 .json（有 prompts 数组），或者干脆是一个条目数组
   脚本文件：悬浮球 .js 本体，或者酒馆助手导出的「脚本导入 .json」 */
function pickFile(id, cb){
  var el=Q(id);
  if(!el){ toast("找不到文件选择框"); return; }
  el.value="";
  el.onchange=function(){
    var f=el.files && el.files[0]; if(!f) return;
    var r=new FileReader();
    r.onload=function(){ cb(String(r.result||""), f.name||""); };
    r.onerror=function(){ toast("读文件失败："+(f.name||"")); };
    r.readAsText(f);
  };
  el.click();
}
/* AI（DeepSeek 等）常常把 JSON 包在 ```json 代码块里、前后还带几句废话，这里统统剥掉 */
function parseLoose(t){
  var s=String(t||"").trim();
  var m=s.match(/```(?:json)?\s*([\s\S]*?)```/);      /* 优先取代码块里的 */
  if(m) s=m[1].trim();
  try{ return JSON.parse(s); }catch(e){}
  var a=s.indexOf("{"), b=s.lastIndexOf("}");          /* 再从第一个 { 到最后一个 } */
  if(a>=0 && b>a){ try{ return JSON.parse(s.slice(a,b+1)); }catch(e2){} }
  return null;
}
function importPresetText(t,name){
  var j=parseLoose(t);
  if(!j){ toast("这不是合法的 JSON（AI 输出的话，把 ``` 代码块也一起复制进来）"); return false; }
  if(Array.isArray(j)) j={name:(name||"导入的预设"), prompts:j};
  if(!j || typeof j!=="object"){ toast("这不是预设文件"); return false; }
  /* 增量补丁：只写了改动条目（甚至只写了 remove），也认 */
  var isPatch = !!(j.remove && j.remove.length) || (j._spec && String(j._spec).indexOf("patch")>=0);
  if(!Array.isArray(j.prompts)) j.prompts=[];
  if(!j.prompts.length && !isPatch){
    toast("文件里没有 prompts 条目，不像预设文件"); return false;
  }
  REMOTE.mf=null; REMOTE.script=null;
  REMOTE.preset=j;
  REMOTE.pv=j.version||j.name||name||"导入的预设";
  REMOTE.plogs=Array.isArray(j.changelog)?j.changelog:[];
  REMOTE.plan=HOOK.plan?HOOK.plan(j):null;
  REMOTE.want={preset:true, script:false};
  openUpdate("plan");
  toast(isPatch
    ? ("补丁："+j.prompts.length+" 条改动"+(j.remove&&j.remove.length?(" / "+j.remove.length+" 条删除"):"")+"，确认后写入")
    : ("读到 "+j.prompts.length+" 条，确认后写入"));
  return true;
}
function importScriptText(t,name){
  var txt=String(t||"");
  if(/^\s*[\[{]/.test(txt)){                     /* 也可能是导出的脚本 json */
    try{
      var j=JSON.parse(txt);
      if(Array.isArray(j) && j.length && j[0] && typeof j[0].content==="string") txt=j[0].content;
      else if(j && typeof j.content==="string") txt=j.content;
    }catch(e){}
  }
  if(!txt || txt.length<200){ toast("这不像完整脚本（内容太短）"); return false; }
  REMOTE.mf=null; REMOTE.preset=null;
  REMOTE.script=txt;
  REMOTE.sv=name||"导入的脚本";
  REMOTE.slogs=["本地导入："+(name||"文件")];
  REMOTE.want={preset:false, script:true};
  openUpdate("plan");
  return true;
}
function importPresetFile(){ mask.classList.remove("on"); pickFile("filePreset", importPresetText); }
function importScriptFile(){ mask.classList.remove("on"); pickFile("fileScript", importScriptText); }

/* ---- 新版本弹窗里的通道行（v1.7）----
   跟「检查更新」那两个勾是一样的，只是多标了「当前版本 → 新版」。
   只想更新预设就把脚本的勾点掉：下面那两行版本对比、更新日志会跟着只剩预设的。 */
function askChanHtml(a){
  var h="";
  function row(key,title,desc,cur,nw,state){
    var on=!!REMOTE.want[key], ok=!!REMOTE.have[key];
    var cls, em;
    if(!ok || state==="na"){ cls="chan na"; em="未提供"; }
    else if(state!=="new"){ cls="chan na"; em=(state==="older"?"你的更新":"已是最新"); }
    else { cls="chan"+(on?" on":""); em="→ "+nw; }
    return '<div class="'+cls+'" data-a="'+key+'">'
      +'<span class="cbx"></span>'
      +'<div class="cx"><b>'+esc(title)+'</b><span>当前 '+esc(cur||"？")
      +(state==="older"?('　·　仓库还是 '+esc(nw||"")):'')+'</span></div>'
      +'<em>'+em+'</em></div>';
  }
  var lv=presetVer()||PRESET.version;
  h+=row("preset","预设","条目内容、正则、采样参数",lv,REMOTE.pv,
         a.newP?"new":(olderThan(REMOTE.pv,lv)?"older":"same"));
  h+=row("script","悬浮球脚本","界面、采集逻辑、头像参数",ORB_VER,REMOTE.sv,
         a.newS?"new":(olderThan(REMOTE.sv,ORB_VER)?"older":"same"));
  return h;
}

/* ---- 更新弹窗底部的「去点个星星」（v1.8）----
   只在有新版本要装的时候露一次。想点就点，不想看点「不再显示」就永远不出现
   （记在 localStorage sk_orb_star=1，跟「跳过某一版」是两码事）。 */
function repoHome(){
  var b=String(REMOTE.base||"").trim(), m;
  m=b.match(/raw\.githubusercontent\.com/([^/]+)/([^/]+)/);
  if(m) return "https://github.com/"+m[1]+"/"+m[2];
  m=b.match(/cdn\.jsdelivr\.net/gh/([^/]+)/([^@/]+)/);   /* 后面的 @分支名 不算仓库名 */
  if(m) return "https://github.com/"+m[1]+"/"+m[2];
  return "https://github.com/zhaoyichan/SillyTavern-Preset-Stockholm";
}
function starHidden(){ var v=null; try{ v=localStorage.getItem("sk_orb_star"); }catch(e){} return v==="1"; }
function starHtml(){
  if(starHidden()) return "";
  return '<div class="star"><span class="stx">用着还行的话，去仓库点个 ⭐ 支持下。</span>'
    +'<button id="stGo">去点星</button><button id="stNo">不再显示</button></div>';
}
function starBind(redraw){
  var g=Q("stGo"), n=Q("stNo");
  if(g) g.onclick=function(){
    try{ if(typeof window.open==="function") window.open(repoHome(),"_blank"); }catch(e){}
    toast("仓库页面已打开，谢谢 ⭐");
  };
  if(n) n.onclick=function(){
    try{ localStorage.setItem("sk_orb_star","1"); }catch(e){}
    if(typeof redraw==="function") redraw();
    toast("以后不再显示这条了");
  };
}

