      +'<p style="font-size:11px;color:var(--ink3);margin:2px 0 10px">'
      +'例如 <b>https://raw.githubusercontent.com/你的账号/仓库名/main</b>'
      +'　或　<b>https://cdn.jsdelivr.net/gh/你的账号/仓库名@main</b></p>'
      +'<p style="font-size:11.5px;color:var(--ink2);margin:0 0 8px">要更新哪一条？（可以只更一个）</p>'
      +chanRow("preset","预设","条目内容、正则、采样参数",presetVer()||PRESET.version)
      +chanRow("script","悬浮球脚本","界面、采集逻辑、头像参数",ORB_VER)
      +'<p style="font-size:11.5px;color:var(--ink2);margin:10px 0 12px">'
      +icon('merge','sm')+' <b>预设按条目合并</b>：只有<b>同名</b>的条目会换成新版内容，'
      +'你自己新增的条目完整保留。<br>'
      +'<span style="color:var(--ink3)">脚本更新会写回脚本库，<b>重开酒馆后生效</b>。'
      +'只填你自己的仓库——别人的仓库可能塞入恶意脚本。</span></p>'
      +'<div class="aside">'
      +'<div class="as-hd">没联网 / 只想装本地文件</div>'
      +'<div class="bt" style="margin-top:6px">'
      +'<button id="impPreset" class="gy">'+icon('merge','sm')+'导入预设文件</button>'
      +'<button id="impScript" class="gy">'+icon('down','sm')+'导入脚本文件</button></div>'
      +'</div>'
      +'<div class="bt"><button id="upCancel">取消</button><button class="go" id="upCheck">检查更新</button></div>';
    dlg.querySelectorAll(".chan").forEach(function(el){
      el.onclick=function(){
        var k=el.getAttribute("data-c");
        if(el.classList.contains("na")) return;      /* 仓库没提供的不能勾 */
        REMOTE.touched=true;                         /* 用户手动动过勾选，就听他的 */
        REMOTE.want[k]=!REMOTE.want[k];
        el.classList.toggle("on", !!REMOTE.want[k]);
      };
    });
    Q("impPreset").onclick=importPresetFile;
    Q("impScript").onclick=importScriptFile;
    Q("upCancel").onclick=function(){mask.classList.remove("on");};
    Q("upCheck").onclick=function(){
      REMOTE.base=Q("repoIn").value.trim();
      try{ localStorage.setItem("sk_orb_repo", REMOTE.base); }catch(e){}
      openUpdate("loading"); upFetch();
    };
  } else if(stage==="loading"){
    dlg.innerHTML='<h3>正在连接仓库…</h3>'
      +'<div class="spinrow"><span class="sp"></span>拉取 update.json</div>';
  } else if(stage==="error"){
    dlg.innerHTML='<h3>'+icon('warn')+'没拉到</h3>'
      +'<div class="upwarn bad">'+esc(arg||"未知错误")+'</div>'
      +'<p style="font-size:11.5px;color:var(--ink3);margin:10px 0 12px">'
      +'常见原因：仓库地址写错、分支不是 main、是私有仓库、或者返回的是网页而不是 JSON。<br>'
      +'用浏览器打开 <b>'+esc(joinUrl(REMOTE.base,"update.json"))+'</b>，能看到一段 JSON 才对。</p>'
      +'<div class="bt"><button id="upCancel3">关闭</button><button class="go" id="upRetry">重试</button></div>';
    Q("upCancel3").onclick=function(){mask.classList.remove("on");};
    Q("upRetry").onclick=function(){openUpdate("loading");upFetch();};
  } else if(stage==="plan"){
    var s=REMOTE.plan||{upd:0,add:0,kept:0,rm:0,same:0,nochange:0,local:0}, h="";
    var nwLb=(REMOTE.sel&&!REMOTE.sel.latest)?"所选版本":"最新";
    var pickTip="";
    if(REMOTE.sel){
      pickTip='<div class="upwarn" style="color:var(--ink2);background:var(--paper2);'
        +'border-color:var(--line)">你选的是 <b>'+esc(REMOTE.sel.tag||"")+'</b>'
        +((REMOTE.sel.date)?('（'+esc(REMOTE.sel.date)+'）'):'')
        +((REMOTE.sel.latest)?'　·　这是最新版。':'　·　这是老版本，更新完等于退回这一版。')
        +'</div>';
    }
    h+=pickTip;
    /* 预设到底有没有变动：逐条比对过（plan.nochange）或者版本号压根一样 → 都算没变动。
