          :'<p style="font-size:11.5px;color:var(--ink3);margin:8px 0 0">（作者没写脚本的更新说明）</p>')
        +'<p style="font-size:11.5px;color:var(--ink3);margin:8px 0 0">'
        +'脚本更新是<b>整段替换</b>（不是合并），写回脚本库后<b>重开酒馆生效</b>。</p>';
    }
    if(!h) h='<div class="upwarn">两个通道都没有可更新的内容。</div>';
    /* 预设没变动就不算进按钮文案：只更新脚本时按钮写「更新脚本」，不写「两个都更新」 */
    var wP=!!(REMOTE.want.preset && REMOTE.preset && !pNoChg);
