      +'<button class="go" id="upGo">'+esc(label)+'</button></div>';
    keptBind();
    Q("upCancel2").onclick=function(){mask.classList.remove("on");};
    Q("upGo").onclick=upApply;
  } else if(stage==="versions"){
    dlg.innerHTML='<h3>'+icon('down','sm')+'选择版本</h3>'
