/* v1.9：「新版没有」的那几条，把名字摆出来。
   这里面混着两类东西 —— 你自己加的，和作者在新版里删掉的。
   脚本手上只有「最新版」这一份参考，没有历史版本可对照，所以不替你判断，
   只列清单；要不要清理由你自己点按钮决定（默认一条不动）。 */
function keptHtml(s){
