/* 「清理」按钮的行为：第一次点只是变文案，再点一次才真删。
   删完立刻照新版重新算一遍清单，弹窗里的数字自己会变。 */
function keptBind(){
  var btn=Q("upDrop");
  if(!btn) return;
  btn.onclick=function(){
    var L=(REMOTE.plan&&REMOTE.plan.keptList)||[];
    if(!L.length) return;
    if(btn.getAttribute("data-cf")!=="1"){
      btn.setAttribute("data-cf","1");
      btn.textContent="再点一次，真的移除 "+L.length+" 条";
      return;
    }
    btn.disabled=true; btn.textContent="正在清理…";
    var ids=L.map(function(x){ return x.id||x.name; });
    HOOK.dropItems(ids,function(ok,msg){
      if(!ok){ openUpdate("error",msg||"清理失败"); return; }
      try{ if(HOOK.plan && REMOTE.preset) REMOTE.plan=HOOK.plan(REMOTE.preset); }catch(e){}
      openUpdate("plan");
      toast(msg||"已清理");
    });
  };
}

