/* 选中某个版本 → 只拉这个版本的文件 → 出清单 */
function upPick(i){
  var v=REMOTE.hist[i];
  if(!v){ openUpdate("error","这一版不存在"); return; }
  REMOTE.sel=v;
  REMOTE.pv=(v.preset&&v.preset.version)||"";
  REMOTE.sv=(v.script&&v.script.version)||"";
  REMOTE.plogs=(v.preset&&v.preset.changelog)||[];
  REMOTE.slogs=v.changelog||(v.script&&v.script.changelog)||[];
  REMOTE.preset=null; REMOTE.script=null;
  var raw=(REMOTE.base||"").trim(), jobs=[];
  if(REMOTE.want.preset && v.preset && v.preset.file) jobs.push("preset");
  if(REMOTE.want.script && v.script && v.script.file) jobs.push("script");
  if(!jobs.length){ openUpdate("error","这一版没有你要更新的通道"); return; }
  openUpdate("loading");
  var k=0;
  (function next(){
    if(k>=jobs.length){ openUpdate("plan"); return; }
    var t=jobs[k++];
    if(t==="preset"){
      HOOK.fetchPreset(joinUrl(raw, v.preset.file), function(ok,j,e){
        if(!ok){ openUpdate("error","预设拉取失败："+e); return; }
        REMOTE.preset=j;
        if(j&&j.name&&!REMOTE.pv) REMOTE.pv=j.name;
        REMOTE.plan=HOOK.plan?HOOK.plan(j):null;
        next();
      });
    }else{
      HOOK.fetchText(joinUrl(raw, v.script.file), function(ok,txt,e){
        if(!ok){ openUpdate("error","脚本拉取失败："+e); return; }
        REMOTE.script=txt; next();
      });
    }
  })();
}

/* 拉取索引 → 按勾选拉各通道文件 → 出清单 */
function upFetch(){
  var raw=(REMOTE.base||"").trim();
  if(!raw){ openUpdate("error","还没填仓库地址"); return; }
  if(isLegacyPresetUrl(raw)){                 /* 老用法：直接贴了预设 json 地址 */
    REMOTE.mf=null; REMOTE.want={preset:true, script:false}; REMOTE.script=null;
    REMOTE.have={preset:true, script:false};
    HOOK.fetchPreset(raw, function(ok,j,err){
      if(!ok){ openUpdate("error", err); return; }
      REMOTE.preset=j;
      REMOTE.pv=(j&&j.name)||"远端";
      REMOTE.plogs=(j&&Array.isArray(j.changelog))?j.changelog:[];
      REMOTE.plan=HOOK.plan?HOOK.plan(j):null;
      openUpdate("plan");
    });
    return;
  }
  HOOK.fetchManifest(joinUrl(raw,"update.json"), function(ok,mf,err){
    if(!ok){ openUpdate("error", err); return; }
    REMOTE.mf=mf; REMOTE.preset=null; REMOTE.script=null; REMOTE.sel=null;
    REMOTE.hist=Array.isArray(mf.history)?mf.history.slice():[];
    REMOTE.pv=(mf.preset&&mf.preset.version)||"";
    REMOTE.plogs=(mf.preset&&mf.preset.changelog)||[];
    REMOTE.sv=(mf.script&&mf.script.version)||"";
    REMOTE.slogs=(mf.script&&mf.script.changelog)||[];
    /* 仓库这次提供了哪几条：缺的那条灰掉，不用三个文件必须凑齐 */
    REMOTE.have={preset:!!(mf.preset&&mf.preset.file), script:!!(mf.script&&mf.script.file)};
    if(!REMOTE.touched) REMOTE.want={preset:REMOTE.have.preset, script:REMOTE.have.script};
    else{
      REMOTE.want.preset=REMOTE.want.preset&&REMOTE.have.preset;
      REMOTE.want.script=REMOTE.want.script&&REMOTE.have.script;
    }
    /* 仓库带了版本列表 → 先给选版本；没带（老仓库）→ 照旧直接拉最新 */
    if(REMOTE.hist.length){ openUpdate("versions"); return; }
    var jobs=[];
    if(REMOTE.want.preset) jobs.push("preset");
    if(REMOTE.want.script) jobs.push("script");
    if(!jobs.length){ openUpdate("error","update.json 里没有你要更新的通道（勾一个再试）"); return; }
    var i=0;
    (function next(){
      if(i>=jobs.length){ openUpdate("plan"); return; }
      var k=jobs[i++];
      if(k==="preset"){
        HOOK.fetchPreset(joinUrl(raw,mf.preset.file), function(ok,j,e){
          if(!ok){ openUpdate("error","预设拉取失败："+e); return; }
          REMOTE.preset=j;
          if(j&&j.name&&!REMOTE.pv) REMOTE.pv=j.name;
          REMOTE.plan=HOOK.plan?HOOK.plan(j):null;
          next();
        });
      }else{
        HOOK.fetchText(joinUrl(raw,mf.script.file), function(ok,t,e){
          if(!ok){ openUpdate("error","脚本拉取失败："+e); return; }
          REMOTE.script=t; next();
        });
      }
    })();
  });
}

/* ========================================================== 启动自动检查更新
   静默拉一次 update.json：有新版本就弹窗问一句「要不要更新」。
   「这次先不」只记下这一版 → 下次再出新版本照样提醒（不会永远闭嘴）。 */
/* 本地预设版本：酒馆没有单独的「预设版本」字段，版本号写在预设名末尾（…v2.0）。
   别拿 PRESET.version 的默认值去跟远端比 —— 那是演示占位值，比了永远不相等，
   会变成每次启动都误报「有新版本」。 */
function presetVer(){
  var nm="";
  try{ nm=String(PRESET.name||""); }catch(e){}
  var m=nm.match(/v(\d+(?:\.\d+)*)\s*$/i);
  return m?("v"+m[1]):"";
}
/* ---- 版本号大小比较（v1.7） ----
   以前只比「字符串相不相等」，于是本地 v1.6 对上仓库 v1.5 也算"不一样"→ 照样弹「有新版本」。
   现在真比大小：只有仓库那版**确实比本地新**才算更新。
   返回  1：a 比 b 新   -1：a 比 b 旧   0：一样   NaN：有一边认不出（比如 "最新"、"beta"） */
function vcmp(a,b){
  function segs(s){
    var m=String(s==null?"":s).trim().match(/v?(\d+(?:\.\d+)*)/i);
    return m?m[1].split(".").map(function(x){return parseInt(x,10)||0;}):null;
  }
  var x=segs(a), y=segs(b);
  if(!x||!y) return NaN;
  var n=Math.max(x.length,y.length);
  for(var i=0;i<n;i++){
    var p=x[i]||0, q=y[i]||0;
    if(p>q) return 1;
    if(p<q) return -1;
  }
  return 0;
}
/* 仓库那版是不是真的更新：认不出版本号一律当「不是」（宁可不弹，也别瞎提醒） */
function newerThan(remote,local){
  if(!remote||!local) return false;
  var c=vcmp(remote,local);
  if(isNaN(c)) return false;
  return c>0;
}
/* 反过来：本地比仓库还新（自己改过 / 仓库还没发） */
function olderThan(remote,local){
  if(!remote||!local) return false;
  var c=vcmp(remote,local);
  if(isNaN(c)) return false;
  return c<0;
}
function updAutoOn(){
  try{ return localStorage.getItem("sk_orb_updauto")!=="0"; }catch(e){ return true; }
}
function updAutoSet(v){ try{ localStorage.setItem("sk_orb_updauto", v?"1":"0"); }catch(e){} }
function updAutoInit(){
  try{
    if(!updAutoOn()) return;
    var b=(REMOTE.base||"").trim();
    if(!b || isLegacyPresetUrl(b)) return;
    setTimeout(updAutoTick, 5000);      /* 别跟启动抢网络 */
  }catch(e){}
}
function updAutoTick(){
  try{
    if(!updAutoOn()) return;
    if(mask && mask.classList.contains("on")){                      /* 有弹窗在，不凑热闹 */
      if(!updAutoTick.__re){ updAutoTick.__re=1; setTimeout(updAutoTick, 25000); }
      return;
    }
    var pn=Q("panel");
    if(pn && pn.classList.contains("open")){ setTimeout(updAutoTick, 30000); return; }  /* 面板开着，等会儿 */
    HOOK.fetchManifest(joinUrl(REMOTE.base,"update.json"), function(ok, mf){
      if(!ok || !mf) return;                                        /* 拉不到就当没事，绝不弹错 */
      var sv=(mf.script&&mf.script.version)||"", pv=(mf.preset&&mf.preset.version)||"";
      var lv=presetVer();                    /* 本地预设版本（从预设名末尾解析） */
      /* v1.7：真比大小。相等、或者本地比仓库还新 → 一律不弹（以前只要字符串不等就弹） */
      var newS=newerThan(sv, ORB_VER), newP=!!lv && newerThan(pv, lv);
      if(!newS && !newP){
        try{
          REMOTE.ahead={
            script: olderThan(sv,ORB_VER) ? {local:ORB_VER, remote:sv} : null,
            preset: (lv && olderThan(pv,lv)) ? {local:lv, remote:pv} : null
          };
          REMOTE.remote={preset:pv, script:sv};
        }catch(e){}
        return;                              /* 平级或超前，闭嘴 */
      }
      try{ REMOTE.remote={preset:pv, script:sv}; REMOTE.ahead=null; }catch(e){}
      var tag="";
      if(Array.isArray(mf.history) && mf.history.length) tag=mf.history[0].tag||"";
      if(!tag) tag=(sv||pv||"new");
      try{ if(localStorage.getItem("sk_orb_skipv")===tag) return; }catch(e){}
      REMOTE.mf=mf; REMOTE.preset=null; REMOTE.script=null; REMOTE.sel=null;
      REMOTE.hist=Array.isArray(mf.history)?mf.history.slice():[];
      REMOTE.pv=pv; REMOTE.sv=sv;
      REMOTE.plogs=(mf.preset&&mf.preset.changelog)||[];
      REMOTE.slogs=(mf.script&&mf.script.changelog)||[];
      REMOTE.have={preset:!!(mf.preset&&mf.preset.file), script:!!(mf.script&&mf.script.file)};
      REMOTE.want={preset:newP&&REMOTE.have.preset, script:newS&&REMOTE.have.script};
      REMOTE.touched=false;
      openUpdate("ask",{tag:tag, sv:sv, pv:pv, newS:newS, newP:newP});
    });
  }catch(e){}
}

/* 写入：先预设（合并）后脚本（整段替换） */
var NEWITEMS=null;   /* v2.0：写入成功后回填的新条目，刷新面板时优先用它 */
function upApply(){
  openUpdate("doing");
  var msgs=[];
  function after(){
    mask.classList.remove("on");
    panelRefresh();
    setTimeout(function(){toast(msgs.join(" ／ ")||"没有可更新的内容");},300);
  }
  function doScript(){
    if(!(REMOTE.want.script && REMOTE.script)){ after(); return; }
    HOOK.applyScript(REMOTE.script, function(ok,msg){
      msgs.push((ok?"✓ ":"✗ ")+msg); after();
    });
  }
  function doPreset(){
    /* v1.6：预设没有变动就干脆不写，只在结果里说一句「预设没有变动，已跳过」 */
    if(!(REMOTE.want.preset && REMOTE.preset)){ doScript(); return; }
    if(REMOTE.pNoChg){ msgs.push("·  预设没有变动，已跳过（你现在的就是这版）"); doScript(); return; }
    HOOK.apply(REMOTE.preset, function(ok,msg,items){
      if(items && items.length) NEWITEMS=items;   /* v2.0：拿写入的返回值，别再重读 */
      msgs.push((ok?"✓ ":"✗ ")+msg); doScript();
    });
  }
  doPreset();
}
/* v2.0：更新完刷新面板。
   ① 优先用写入返回的新条目 —— 官方文档说 updatePresetWith 的返回值就是「更新后的预设」，
      比写完之后再调 getPreset 重读可靠。以前就是靠重读，结果面板一直显示旧内容，
      而酒馆自己的界面是新的：两边读的不是同一份东西。
   ② 拿不到返回值才退回重读：重读后条目数还在变，说明写入还没同步到读取那一侧，
      延迟再试几轮（累计约 2.5 秒），等它稳下来再画。
   ③ 出错要说出来 —— 以前 catch 里是空的，界面不动也不吭声，
      根本看不出是刷新崩了还是压根没更新。 */
function panelRefresh(){
  var paint=function(){
    try{ gSync();renderList();updFoot(); }
    catch(e){ try{ console&&console.log&&console.log("[orb] 面板刷新出错",e); }catch(_){}
              try{ toast("面板刷新出错："+e); }catch(_){} }
  };
  if(NEWITEMS && NEWITEMS.length){ ITEMS=NEWITEMS; NEWITEMS=null; paint(); return; }
  var delays=[0,300,700,1500], k=0, last=-1;
  (function step(){
    try{ loadItems(); }
    catch(e){ try{ console&&console.log&&console.log("[orb] 重读预设出错",e); }catch(_){} }
    if(ITEMS.length!==last && k<delays.length-1){ last=ITEMS.length; k++; setTimeout(step,delays[k]); return; }
    paint();
  })();
}
Q("btnUp").onclick=function(){openUpdate("check");};

