var AVMAP = {}; AVLIST.forEach(function(x){ AVMAP[x.k]=x; });
var AVSET = { orb:"g1", face:"g1", hero:"w1", sq:{}, fc:{}, hz:{} };
var AVDEF = {}; AVLIST.forEach(function(x){
  AVDEF[x.k]={ b:x.b, f:x.f || x.b, h:x.h };   /* f 没单独调过就跟球用同一套 */
});

/* orb→sq  face→fc  hero→hz：三组参数各自独立，互不干扰 */
function avGroup(g){ return (g==="hero") ? "hz" : (g==="face" ? "fc" : "sq"); }
function avGet(g,k){
  var pool = AVSET[avGroup(g)];
  if(!pool[k]){
    var d = AVDEF[k] || {b:[1,0,0], f:[1,0,0], h:[1,0,0]};
    pool[k] = (g==="hero" ? d.h : (g==="face" ? d.f : d.b)).slice();
  }
  return pool[k];
}
function avCss(p){
  return "translate(-50%,-50%) translate("+p[1]+"%,"+p[2]+"%) scale("+p[0]+")";
}
function avPaint(el, g, k){
  if(!el || !el.style) return;
  var d = AVMAP[k]; if(!d) return;
  el.src = d.src;
  el.style.transform = avCss(avGet(g,k));
}
function applyAvatar(){
  /* 组名必须与弹窗里用的 orb/face/hero 一致，否则读错参数池（face 会读到球的 sq） */
  avPaint(Q("orbImg"),  "orb",  AVSET.orb);
  avPaint(Q("faceImg"), "face", AVSET.face);
  avPaint(Q("heroImg"), "hero", AVSET.hero);
}
function saveAvatar(){
