}
function avatarInit(){
  try{
    var v = JSON.parse(localStorage.getItem("sk_avatar")||"null");
    if(v && typeof v==="object"){
      if(AVMAP[v.orb])  AVSET.orb  = v.orb;
      if(AVMAP[v.face]) AVSET.face = v.face;
      if(AVMAP[v.hero]) AVSET.hero = v.hero;
      if(v.sq && typeof v.sq==="object") AVSET.sq = v.sq;
      if(v.hz && typeof v.hz==="object") AVSET.hz = v.hz;
      if(v.fc && typeof v.fc==="object") AVSET.fc = v.fc;
      else if(v.sq && typeof v.sq==="object") AVSET.fc = JSON.parse(JSON.stringify(v.sq));
      /* ↑ 旧存档里面板头像与球共用 sq，升级时先继承，之后各调各的 */
    }
  }catch(e){}
  /* 兜底：选项改过之后旧存档可能指向已删的图 */
  if(!AVMAP[AVSET.orb])  AVSET.orb  = "g1";
  if(!AVMAP[AVSET.face]) AVSET.face = "g1";
  if(!AVMAP[AVSET.hero]) AVSET.hero = "w1";
  applyAvatar();
}

