/* 绑定某一组的裁剪框：按住拖 = 改位置，滚轮 = 改缩放 */
function avBindOne(g){
  var frame = Q("avClip_"+g), img = Q("avImg_"+g);
  if(!frame || !img) return;
  var k = AVSET[g], p = avGet(g,k), d = AVMAP[k] || AVMAP.g1;
  var slider = Q("avZoom_"+g), zlab = Q("avZv_"+g);
  function paint(){
    img.src = d.src;
    img.style.transform = avCss(p);
  }
  function setZ(z){
    p[0] = Math.max(0.4, Math.min(8, Math.round(z*100)/100));
    paint(); showZ(); saveAvatar(); applyAvatar();
  }
  function showZ(){
    var v = Math.round(p[0]*100)/100;
    if(zlab) zlab.textContent = v.toFixed(2)+"×";
    if(slider) slider.value = Math.round(p[0]*100);
  }
  paint(); showZ();
  if(slider) slider.oninput = function(){
    p[0] = Math.max(0.4, Math.min(8, (+slider.value)/100));
    paint(); showZ(); applyAvatar();   /* 拖动时小球/面板上那张也实时跟着变 */
  };
  if(slider) slider.onchange = function(){ saveAvatar(); };

  /* 拖动位置 + 双指捏合缩放（手机没有滚轮，靠这两个） */
  var sx=0, sy=0, ox=0, oy=0, on=false;
  var pts={}, pinch=null;
  function dist(){
    var ks=Object.keys(pts); if(ks.length<2) return 0;
    var a=pts[ks[0]], b=pts[ks[1]];
    return Math.sqrt((a.x-b.x)*(a.x-b.x)+(a.y-b.y)*(a.y-b.y));
  }
  frame.addEventListener("pointerdown", function(e){
    pts[e.pointerId]={x:e.clientX,y:e.clientY};
    var ks=Object.keys(pts);
    if(ks.length>=2){                 /* 第二根手指落下 → 进入捏合，停止拖动 */
      on=false;
      pinch={d:dist()||1, z:p[0]};
      return;
    }
    var r = frame.getBoundingClientRect();
    if(!r.width) return;
    sx=e.clientX; sy=e.clientY; ox=p[1]; oy=p[2]; on=true;
    try{ frame.setPointerCapture(e.pointerId); }catch(_){}
    e.preventDefault();
  });
  frame.addEventListener("pointermove", function(e){
    if(pts[e.pointerId]) pts[e.pointerId]={x:e.clientX,y:e.clientY};
    if(pinch){
      var d0=dist();
      if(d0>0 && pinch.d>0){
        p[0]=Math.max(0.4, Math.min(8, Math.round(pinch.z*(d0/pinch.d)*100)/100));
        paint(); showZ(); applyAvatar();
      }
      e.preventDefault();
      return;
    }
    if(!on) return;
    var r = frame.getBoundingClientRect();
    if(!r.width) return;
    p[1] = Math.round((ox + (e.clientX-sx)/r.width*100)*10)/10;
    p[2] = Math.round((oy + (e.clientY-sy)/r.height*100)*10)/10;
    paint();
  });
  function up(e){
    delete pts[e.pointerId];
    if(Object.keys(pts).length<2) pinch=null;
    try{ frame.releasePointerCapture(e.pointerId); }catch(_){}
    if(on){ on=false; saveAvatar(); applyAvatar(); }
    else if(pinch===null){ saveAvatar(); applyAvatar(); }
  }
  frame.addEventListener("pointerup", up);
  frame.addEventListener("pointercancel", up);
  frame.addEventListener("wheel", function(e){
    e.preventDefault();
    setZ(p[0] * (e.deltaY < 0 ? 1.08 : 0.925));
  }, {passive:false});
}
/* 把当前三组的自定义参数导出成 JSON（调好后发给作者即可固化成默认值） */
