/* ---- 自动采集：AI 每出一轮就自动刷新（底部「自动」可关） ----
   做法：注册酒馆事件（新楼层/刷楼层/改楼层/换聊天）→ 触发；
   事件不可用时退化为轮询 lastMessageId。 */
var AUTO=true, autoBusy=false, autoTimer=0, lastTurn=-1, autoSrc="";
try{ AUTO = localStorage.getItem("sk_orb_auto")!=="0"; }catch(e){}
function paintAuto(){
  var el=Q("btnAuto"); if(!el) return;
  el.classList.toggle("on", AUTO);
  el.title = AUTO ? ("自动采集：开"+(autoSrc?"（"+autoSrc+"）":"")+" · 每轮自动刷新")
                  : "自动采集：关 · 只能手动点「采集」";
}
function autoTick(force){
  if(!AUTO && !force) return;
  if(autoBusy) return;
  autoBusy=true;
  HOOK.collect(function(d,err){
    autoBusy=false;
    if(err || !d) return;                    /* 静默：没读到 state 不弹错误打扰你 */
    if(!force && d.turn===lastTurn) return;  /* 同一轮不重复刷 */
    lastTurn=d.turn; SAMPLE=d; apply(d);
    if(Q("panel").classList.contains("open"))
      toast(d.stale?("R"+d.turn+"（来自更早楼层）"):("已更新到 R"+d.turn));
  });
}
function autoKick(){ clearTimeout(autoTimer); autoTimer=setTimeout(function(){autoTick(false);},900); }
Q("btnAuto").onclick=function(){
  AUTO=!AUTO;
  try{ localStorage.setItem("sk_orb_auto", AUTO?"1":"0"); }catch(e){}
  paintAuto();
  toast(AUTO?"自动采集：开":"自动采集：关");
  if(AUTO) autoKick();
};
