  /* 球右上角原来有个「有不可逆」的小红点，用不上，去掉了（d.irreversible 只在这里显示） */
  Q("footSt").innerHTML=
    "<b>采集自 R"+d.turn+"</b> · "+new Date().toLocaleTimeString("zh-CN",{hour12:false});
}

/* ========================================================== 开关面板 */
var orb=Q("orb"),panel=Q("panel");
orb.onclick=function(){
  if(orb.__justDragged) return;
  if(panel.classList.contains("open")){panel.classList.remove("open");return;}
  if(firstRun()) return;      /* 首次：说明先弹，点「知道了」后面板才展开 */
  openPanel();
};
Q("btnLock").onclick=function(){setLock(!locked);};
Q("btnClose").onclick=function(){panel.classList.remove("open");};
var btnTheme=Q("btnTheme");
function paintTheme(){
  btnTheme.innerHTML=icon(host.classList.contains("night")?"moon":"sun","sm");
}
btnTheme.onclick=function(){host.classList.toggle("night");paintTheme();};
pdoc.addEventListener("mousedown",function(e){
  if(!panel.classList.contains("open"))return;
  var t=e.target;
  /* 面板挂在 Shadow DOM 里：从外面看，面板内部的任何点击都会被重定向成宿主节点
     （id = sk-orb-host），所以必须先把这种情况判为「面板内」，否则点一下就关面板 */
  if(t && t.id==="sk-orb-host")return;
  if(panel.contains(t)||orb.contains(t))return;
  if(mask.classList.contains("on"))return;
  panel.classList.remove("open");});

/* 注：演示页顶部的 ghost 按钮只在 orb_v7.html 预览里存在，
   打包进酒馆时那一段会被 build_orb.py 去掉，所以这里不依赖它们。 */

/* 填充按钮图标（全部 SVG） */
Q("btnAvatar").innerHTML=icon("avatar","sm");
Q("btnAbout").innerHTML=icon("about","sm");
Q("btnUp").innerHTML=icon("down","sm");
Q("btnClose").innerHTML=icon("close","sm");
Q("btnAdd").innerHTML=icon("plus","sm")+"新增条目";
Q("btnReset").innerHTML=icon("reset","sm");
Q("btnGrp").innerHTML=icon("merge","sm");
Q("btnGrp").title="分组管理：新建组 / 全部展开折叠";
Q("btnRefresh").innerHTML=icon("refresh","sm")+"采集";
Q("btnSave").innerHTML=icon("save","sm")+"写入预设";
Q("btnUp2").innerHTML=icon("down","sm")+"更新";
Q("btnUp2").title="预设 / 脚本 在线更新";
try{ var rb=localStorage.getItem("sk_orb_repo"); if(rb) REMOTE.base=rb; }catch(e){}
Q("btnUp2").onclick=function(){openUpdate("check");};
paintTheme();

/* 恢复锁定状态 */
try{setLock(localStorage.getItem("sk_orb_lock")==="1");}catch(e){setLock(false);}
gLoad();applyUI();          /* v1.3：读分组覆盖表 + 应用手机版/电脑版 */
dragInit();avatarInit();gSync();renderList();updFoot();renderNow(SAMPLE);autoInit();updAutoInit();


  /* 首次启动：读预设条目；读不到就提示 */
  if(!loadItems()){
    try{ var s=Q("sub"); if(s) s.textContent="读不到预设条目（请确认已加载预设）"; }catch(e){}
  }
  renderList(); updFoot(); renderNow(null);

  if(__MISS__.length){
    try{ localStorage.setItem("sk_orb_missing", __MISS__.join(",")); }catch(e){}
    console.warn("[SK-ORB] 面板里缺少这些元素: " + __MISS__.join(","));
  }
})();

